void read_binary_stl(const std::string& filename, std::string& model_id, std::string& code,
    std::string& ml_name, std::string& ml_region, std::string& ml_id) {
    std::ifstream file( encode_path(filename.c_str()), std::ios::binary);
    if (!file) {
        return;
    }

    try {
        // Read the first 80 bytes
        char data[80];
        file.read(data, 80);
        if (!file) {
            file.close();
            return;
        }

        if (data[0] == '\0' || data[0] == ' ') {
            file.close();
            return;
        }

        /*include ml info*/
        std::string ext_content(data);
        std::string ml_content;
        std::string mw_content;

        size_t pos = ext_content.find('&');
        if (pos != std::string::npos) {
            mw_content = ext_content.substr(0, pos);
            ml_content = ext_content.substr(pos + 1);
        }

        if (ml_content.empty() && ext_content.find("ML") != std::string::npos) {
            ml_content = ext_content;
        }

        if (mw_content.empty() && ext_content.find("MW") != std::string::npos) {
            mw_content = ext_content;
        }

        /*parse ml info*/
        if (!ml_content.empty()) {
            std::istringstream iss(ml_content);
            std::string token;
            std::vector<std::string> result;
            while (iss >> token) {
                if (token.find(' ') == std::string::npos) {
                    result.push_back(token);
                }
            }

            if (result.size() == 4 && result[0] == "ML") {
                ml_region   = result[1];
                ml_name     = result[2];
                ml_id       = result[3];
            }
        }

        /*parse mw info*/
        if (!mw_content.empty()) {
            std::istringstream iss(mw_content);
            std::string token;
            std::vector<std::string> result;
            while (iss >> token) {
                if (token.find(' ') == std::string::npos) {
                    result.push_back(token);
                }
            }

            if (result.size() == 4 && result[0] == "MW") {
                model_id    = result[2];
                code        = result[3];
            }
        }

        file.close();
    }
    catch (...) {
        BOOST_LOG_TRIVIAL(warning) << current_exception_message();
    }
    return;
}

// BBS: backup & restore
std::vector<size_t> Plater::priv::load_files(const std::vector<fs::path>& input_files, LoadStrategy strategy, bool ask_multi)
{
    std::vector<size_t> empty_result;
    bool dlg_cont = true;
    bool is_user_cancel = false;
    bool translate_old = false;
    int current_width, current_depth, current_height, project_filament_count = 1;

    if (input_files.empty())
        return std::vector<size_t>();

    if (!input_files.empty())
       q->m_3mf_path = input_files[0].string();

    // BBS
    int filaments_cnt = config->opt<ConfigOptionStrings>("filament_colour")->values.size();
    bool one_by_one = input_files.size() == 1 || printer_technology == ptSLA/* || filaments_cnt <= 1*/;
    if (! one_by_one) {
        for (const auto &path : input_files) {
            if (std::regex_match(path.string(), pattern_bundle)) {
                one_by_one = true;
                break;
            }
        }
    }

    bool load_model = strategy & LoadStrategy::LoadModel;
    bool load_config = strategy & LoadStrategy::LoadConfig;
    bool imperial_units = strategy & LoadStrategy::ImperialUnits;
    bool silence = strategy & LoadStrategy::Silence;

    BOOST_LOG_TRIVIAL(info) << boost::format("load_model %1%, load_config %2%, input_files size %3%")%load_model %load_config %input_files.size();

    const auto loading = _L("Loading") + dots;
    ProgressDialog dlg(loading, "", 100, find_toplevel_parent(q), wxPD_AUTO_HIDE | wxPD_CAN_ABORT | wxPD_APP_MODAL);
    wxBusyCursor busy;

    auto *new_model = (!load_model || one_by_one) ? nullptr : new Slic3r::Model();
    std::vector<size_t> obj_idxs;

    std::string  designer_model_id;
    std::string  designer_country_code;
    std::string  makerlab_region;
    std::string  makerlab_name;
    std::string  makerlab_id;

    int answer_convert_from_meters          = wxOK_DEFAULT;
    int answer_convert_from_imperial_units  = wxOK_DEFAULT;
    int tolal_model_count                   = 0;

    int progress_percent = 0;
    int total_files = input_files.size();
    const int stage_percent[IMPORT_STAGE_MAX+1] = {
            5,      // IMPORT_STAGE_RESTORE
            10,     // IMPORT_STAGE_OPEN
            30,     // IMPORT_STAGE_READ_FILES
            50,     // IMPORT_STAGE_EXTRACT
            60,     // IMPORT_STAGE_LOADING_OBJECTS
            70,     // IMPORT_STAGE_LOADING_PLATES
            80,     // IMPORT_STAGE_FINISH
            85,     // IMPORT_STAGE_ADD_INSTANCE
            90,      // IMPORT_STAGE_UPDATE_GCODE
            92,     // IMPORT_STAGE_CHECK_MODE_GCODE
            95,     // UPDATE_GCODE_RESULT
            98,     // IMPORT_LOAD_CONFIG
            99,     // IMPORT_LOAD_MODEL_OBJECTS
            100
     };
    const int step_percent[LOAD_STEP_STAGE_NUM+1] = {
            5,     // LOAD_STEP_STAGE_READ_FILE
            30,     // LOAD_STEP_STAGE_GET_SOLID
            60,     // LOAD_STEP_STAGE_GET_MESH
            100
     };

    const float INPUT_FILES_RATIO            = 0.7;
    const float INIT_MODEL_RATIO             = 0.75;
    const float CENTER_AROUND_ORIGIN_RATIO   = 0.8;
    const float LOAD_MODEL_RATIO             = 0.9;
    bool        import_obj_or_stl            = false;
    for (size_t i = 0; i < input_files.size(); ++i) {
        int file_percent = 0;

#ifdef _WIN32
        auto path = input_files[i];
        // On Windows, we swap slashes to back slashes, see GH #6803 as read_from_file() does not understand slashes on Windows thus it assignes full path to names of loaded objects.
        path.make_preferred();
#else  // _WIN32
       // Don't make a copy on Posix. Slash is a path separator, back slashes are not accepted as a substitute.
        const auto &path = input_files[i];
#endif // _WIN32
        const auto filename         = path.filename();
        int  progress_percent = static_cast<int>(100.0f * static_cast<float>(i) / static_cast<float>(input_files.size()));
        const auto real_filename    = (strategy & LoadStrategy::Restore) ? input_files[++i].filename() : filename;
        const auto dlg_info         = _L("Loading file") + ": " + from_path(real_filename);
        BOOST_LOG_TRIVIAL(trace) << boost::format("load file %1%") % filename;
        dlg_cont = dlg.Update(progress_percent, dlg_info);
        if (!dlg_cont) return empty_result;

        const bool type_3mf = std::regex_match(path.string(), pattern_3mf);
        // const bool type_zip_amf = !type_3mf && std::regex_match(path.string(), pattern_zip_amf);
        const bool type_any_amf = !type_3mf && std::regex_match(path.string(), pattern_any_amf);
        const bool type_step = boost::algorithm::iends_with(path.string(), ".stp") ||
                               boost::algorithm::iends_with(path.string(), ".step");
        // const bool type_prusa   = std::regex_match(path.string(), pattern_prusa);
        const bool may_have_texture = type_3mf
            || boost::algorithm::iends_with(path.string(), ".obj")
            || boost::algorithm::iends_with(path.string(), ".glb")
            || boost::algorithm::iends_with(path.string(), ".gltf")
            || boost::algorithm::iends_with(path.string(), ".fbx");
        const float input_files_ratio = may_have_texture ? 0.12f : INPUT_FILES_RATIO;
        const float init_model_ratio = may_have_texture ? 0.15f : INIT_MODEL_RATIO;
        const float center_around_origin_ratio = may_have_texture ? 0.18f : CENTER_AROUND_ORIGIN_RATIO;
        const float load_model_ratio = may_have_texture ? 0.20f : LOAD_MODEL_RATIO;

        Slic3r::Model model;
        // Standard 3MF colors for the single texture-import dialog. The painting is applied
        // from these bindings after the dialog, so they must outlive the 3mf reader scope.
        std::shared_ptr<Slic3r::TexturedMesh> standard_3mf_color_mesh;
        wxString standard_3mf_hint;
        std::map<int, std::vector<std::string>> color_group_map;
        VolumeColorInfoMap volume_color_data;
        bool has_3mf_textures = false;
        bool has_3mf_unit = false;
        En3mfType en_3mf_file_type = En3mfType::From_BBS;
        auto add_missing_filaments = [this, &model]() {
            std::set<int> extruderIds;
            for (ModelObject *o : model.objects) {
                if (o->config.option("extruder")) extruderIds.insert(o->config.extruder());
                for (auto volume : o->volumes) {
                    if (volume->config.option("extruder")) extruderIds.insert(volume->config.extruder());
                    // The current print preset already refers to existing filaments, only the model's own ids can exceed them.
                    for (int extruder : volume->get_extruders({})) { extruderIds.insert(extruder); }
                }
            }
            int size = extruderIds.size() == 0 ? 0 : *(extruderIds.rbegin());

            // Insert physical filaments before mixed ones. set_num_filaments() takes the total count,
            // so growing it by the physical count would truncate mixed slots and append physicals after them.
            const int physical_size   = int(sidebar->combos_filament().size());
            const int target_physical = std::min(size, int(MAX_PHYSICAL_FILAMENT_COUNT));
            if (physical_size < target_physical) {
                std::vector<std::pair<wxColour, std::string>> new_filaments;
                new_filaments.reserve(size_t(target_physical - physical_size));
                for (int i = physical_size; i < target_physical; ++i)
                    new_filaments.emplace_back(Plater::get_next_color_for_filament(), std::string());
                sidebar->add_custom_filaments(new_filaments);
            }
            wxGetApp().get_tab(Preset::TYPE_PRINT)->update();
        };
        // BBS: add auxiliary files related logic
        bool load_aux = strategy & LoadStrategy::LoadAuxiliary, load_old_project = false;
        if (load_model && load_config && type_3mf) {
            load_aux = true;
            strategy = strategy | LoadStrategy::LoadAuxiliary;
        }
        if (load_config) strategy = strategy | LoadStrategy::CheckVersion;
        bool is_project_file = false;
        BOOST_LOG_TRIVIAL(info) << boost::format("is_project_file %1%, type_3mf %2%") % is_project_file % type_3mf;
        try {
            if (type_3mf) {
                DynamicPrintConfig config;
                Semver             file_version;
                std::optional<bool> loaded_multi_nozzle_diameter_mode;
                // The nozzle keys exactly as the file has them; the merge with defaults below fills missing keys.
                DynamicPrintConfig  file_nozzle_keys;
                {
                    DynamicPrintConfig config_loaded;

                    // BBS: add part plate related logic
                    PlateDataPtrs             plate_data;
                    ConfigSubstitutionContext config_substitutions{ForwardCompatibilitySubstitutionRule::Enable};
                    std::vector<Preset *>     project_presets;
                    // BBS: backup & restore
                    q->skip_thumbnail_invalid = true;
                    model = Slic3r::Model::read_from_archive(path.string(), &config_loaded, &config_substitutions, en_3mf_file_type, strategy, &plate_data, &project_presets,
                                                             &file_version,
                                                             [this, &dlg, real_filename, &progress_percent, &file_percent, stage_percent, input_files_ratio, total_files, i,
                                                              &is_user_cancel](int import_stage, int current, int total, bool &cancel) {
                                                                 bool     cont = true;
                                                                 float percent_float = (100.0f * (float)i / (float)total_files) + input_files_ratio * ((float)stage_percent[import_stage] + (float)current * (float)(stage_percent[import_stage + 1] - stage_percent[import_stage]) /(float) total) / (float)total_files;
                                                                 BOOST_LOG_TRIVIAL(trace) << "load_3mf_file: percent(float)=" << percent_float << ", stage = " << import_stage << ", curr = " << current << ", total = " << total;
                                                                 progress_percent = (int)percent_float;
                                                                 wxString msg  = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                                                                 cont          = dlg.Update(progress_percent, msg);
                                                                 cancel        = !cont;
                                                                 if (cancel)
                                                                     is_user_cancel = cancel;
                                                             }, nullptr, &color_group_map, &volume_color_data, &has_3mf_textures, &has_3mf_unit);
                    if (const auto *mode = config_loaded.option<ConfigOptionBool>("multi_nozzle_diameter_mode"))
                        loaded_multi_nozzle_diameter_mode = mode->value;
                    const ConfigOption *selected_diameters =
                        config_loaded.option("filament_diameter_map");
                    const ConfigOption *per_slot_diameters =
                        config_loaded.option("extruder_nozzle_diameter");
                    BOOST_LOG_TRIVIAL(info)
                        << "multi-diameter project load: raw mode_present="
                        << loaded_multi_nozzle_diameter_mode.has_value()
                        << ", mode=" << loaded_multi_nozzle_diameter_mode.value_or(false)
                        << ", selected="
                        << (selected_diameters ? selected_diameters->serialize() : "<missing>")
                        << ", per_slot="
                        << (per_slot_diameters ? per_slot_diameters->serialize() : "<missing>");
                    BOOST_LOG_TRIVIAL(info)
                                            << boost::format("plate_data.size %1%, project_preset.size %2%, is_bbs_3mf %3%, file_version %4% \n") % plate_data.size() %
                                                   project_presets.size() % (en_3mf_file_type == En3mfType::From_BBS) % file_version.to_string();

                    // 1. add extruder for prusa model if the number of existing extruders is not enough
                    // 2. add extruder for BBS or Other model if only import geometry
                    const bool need_filament_add = en_3mf_file_type == En3mfType::From_Prusa || (load_model && !load_config);
                    // Other non-Bambu models may open the color import dialog, which adds only the filaments the user
                    // confirms there, so their filaments are added below once it is known the dialog is not shown.
                    const bool defer_filament_add = load_model && en_3mf_file_type == En3mfType::From_Other;
                    if (need_filament_add && !defer_filament_add)
                        add_missing_filaments();

                    std::string import_project_action = wxGetApp().app_config->get("import_project_action");
                    LoadType load_type;
                    if (import_project_action.empty())
                        load_type = LoadType::Unknown;
                    else
                        load_type  = static_cast<LoadType>(std::stoi(import_project_action));

                    // check the loaded config if its not from BBL
                    if (!is_bbl_vendor_config(config_loaded, wxGetApp().preset_bundle) && !check_project_config(config_loaded)) {
                        load_config = false;
                        q->get_notification_manager()->push_notification(NotificationType::CustomNotification,
                            NotificationManager::NotificationLevel::WarningNotificationLevel,
                            into_u8(_L("The 3mf file has invalid config, load geometry data only")));
                    }

                    // BBS: version check
                    Semver app_version = *(Semver::parse(SLIC3R_VERSION));
                    if (en_3mf_file_type == En3mfType::From_Prusa) {
                        // do not reset the model config
                        load_config = false;
                        if(load_type != LoadType::LoadGeometry)
                            q->get_notification_manager()->push_notification(NotificationType::CustomNotification,
                                NotificationManager::NotificationLevel::WarningNotificationLevel,
                                into_u8(_L("The 3mf is not from Bambu Lab, load geometry data and color data only.")));
                    }
                    else if (load_config && (file_version.maj() > app_version.maj())) {
                        // version mismatch, only load geometries
                        //load_config = false;
                        if (!load_model) {
                            // only load config case, return directly
                            show_info(q, _L("The Config can not be loaded."), _L("Load 3mf"));
                            q->skip_thumbnail_invalid = false;
                            return empty_result;
                        }
                        load_old_project = true;
                        // select view to 3D
                        //q->select_view_3D("3D");
                        // select plate 0 as default
                        //q->select_plate(0);
                        if (load_type != LoadType::LoadGeometry) {
                            if (en_3mf_file_type == En3mfType::From_BBS)
                                show_info(q, _L("Due to the lower version of Bambu Studio, this 3mf file cannot be fully loaded. Please update Bambu Studio to the latest version"), _L("Load 3mf"));
                            else
                                q->get_notification_manager()->push_notification(NotificationType::CustomNotification,
                                    NotificationManager::NotificationLevel::WarningNotificationLevel,
                                    into_u8(_L("The 3mf is not from Bambu Lab, load geometry data and color data only.")));
                        }
                        //for (ModelObject *model_object : model.objects) {
                        //    model_object->config.reset();
                        //    // Is there any modifier or advanced config data?
                        //    for (ModelVolume *model_volume : model_object->volumes) model_volume->config.reset();
                        //}
                    }
                    else if (load_config && (file_version > app_version)) {
                        Semver cloud_ver;
                        if (wxGetApp().app_config->has("app", "cloud_version")) {
                            std::string cloud_version = wxGetApp().app_config->get("app", "cloud_version");
                            if (!cloud_version.empty())
                                cloud_ver                 = *(Semver::parse(cloud_version));
                            else
                                cloud_ver = app_version;
                        } else {
                            cloud_ver = app_version;
                        }
                        int file_version_cc = file_version.patch()/100;
                        int app_version_cc = app_version.patch()/100;

                        if ((file_version.min() != app_version.min()) || (file_version_cc != app_version_cc)) {
                            if (config_substitutions.unrecogized_keys.size() > 0) {
                                // std::string context = into_u8(text);
                                wxString context;
                                if (wxGetApp().app_config->get("user_mode") == "develop") {
                                    context = _L("Found following keys unrecognized:\n");
                                    for (auto& key : config_substitutions.unrecogized_keys) {
                                        context += "  -";
                                        context += key;
                                        context += ";\n";
                                    }
                                }
                                context += "\n\n";
                                Newer3mfVersionDialog newer_dlg(q, &file_version, &cloud_ver, context);
                                newer_dlg.ShowModal();
                            }
                            else {
                                //if the minor version is not matched
                                //if (file_version.min() != app_version.min()) {
                                Newer3mfVersionDialog newer_dlg(q, &file_version, &cloud_ver, "");
                                    auto res = newer_dlg.ShowModal();
                                //}
                            }
                        }
                    }
                    else if (load_config && config_loaded.empty()) {
                        load_config = false;
                        // Other non-Bambu 3MF models get their source warning with the color handling below.
                        if (wxGetApp().app_config->get_bool("skip_non_bambu_3mf_warning") != true &&
                            !(load_model && en_3mf_file_type == En3mfType::From_Other)) {
                            wxString warn_text = file_version.maj() == 0 && file_version.min() == 0 && file_version.patch() == 0
                                ? _L("The 3mf is not from Bambu Lab, load geometry data and color data only.")
                                : _L("The 3mf is generated by old Bambu Studio, load geometry data only.");
                            q->get_notification_manager()->push_notification(NotificationType::CustomNotification,
                                NotificationManager::NotificationLevel::WarningNotificationLevel,
                                into_u8(warn_text));
                        }
                    }
                    else if (!load_config) {
                        // reset config except color
                        for (ModelObject *model_object : model.objects) {
                            bool has_extruder = model_object->config.has("extruder");
                            int  extruder_id  = -1;
                            // save the extruder information before reset
                            if (has_extruder) { extruder_id = model_object->config.extruder(); }

                            model_object->config.reset();

                            // restore the extruder after reset
                            if (has_extruder) { model_object->config.set("extruder", extruder_id); }

                            // Is there any modifier or advanced config data?
                            for (ModelVolume *model_volume : model_object->volumes) {
                                has_extruder = model_volume->config.has("extruder");
                                if (has_extruder) { extruder_id = model_volume->config.extruder(); }

                                model_volume->config.reset();

                                if (has_extruder) { model_volume->config.set("extruder", extruder_id); }
                            }
                        }
                    }

                    // plate data
                    if (plate_data.size() > 0) {
                        BOOST_LOG_TRIVIAL(info) << boost::format("import 3mf UPDATE_GCODE_RESULT \n");
                        wxString msg = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                        dlg_cont     = dlg.Update(progress_percent, msg);
                        if (!dlg_cont) {
                            q->skip_thumbnail_invalid = false;
                            return empty_result;
                        }

                        Semver old_version(1, 5, 9);
                        if ((en_3mf_file_type == En3mfType::From_BBS) && (file_version < old_version) && load_model && load_config && !config_loaded.empty()) {
                            translate_old = true;
                            partplate_list.get_plate_size(current_width, current_depth, current_height);
                        }

                        if (load_config) {
                            if (translate_old) {
                                //set the size back
                                partplate_list.reset_size(current_width + Bed3D::Axes::DefaultTipRadius, current_depth + Bed3D::Axes::DefaultTipRadius, current_height, false);
                            }
                            if(auto* color_opt = config_loaded.option<ConfigOptionStrings>("filament_colour"))
                                project_filament_count = color_opt->size();
                            partplate_list.load_from_3mf_structure(plate_data, project_filament_count);
                            partplate_list.update_slice_context_to_current_plate(background_process);
                            this->preview->update_gcode_result(partplate_list.get_current_slice_result());
                            release_PlateData_list(plate_data);
                            sidebar->obj_list()->reload_all_plates();
                            q->suppress_background_process(true);
                        } else {
                            partplate_list.reload_all_objects();
                        }
                    }

                    // BBS:: project embedded presets
                    if ((project_presets.size() > 0) && load_config) {
                        // load project embedded presets
                        PresetsConfigSubstitutions preset_substitutions;
                        PresetBundle &             preset_bundle = *wxGetApp().preset_bundle;
                        preset_substitutions                     = preset_bundle.load_project_embedded_presets(project_presets, ForwardCompatibilitySubstitutionRule::Enable);
                        if (!preset_substitutions.empty()) show_substitutions_info(preset_substitutions);
                    }
                    if (project_presets.size() > 0) {
                        for (unsigned int i = 0; i < project_presets.size(); i++) { delete project_presets[i]; }
                        project_presets.clear();
                    }

                    if (load_config && !config_loaded.empty()) {
                        BOOST_LOG_TRIVIAL(info) << boost::format("import 3mf IMPORT_LOAD_CONFIG \n");
                        wxString msg = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                        dlg_cont     = dlg.Update(progress_percent, msg);
                        if (!dlg_cont) {
                            q->skip_thumbnail_invalid = false;
                            return empty_result;
                        }

                        // Based on the printer technology field found in the loaded config, select the base for the config,
                        PrinterTechnology printer_technology = Preset::printer_technology(config_loaded);

                        // apply_only() creates every listed key, so copy only the keys the file has: a file
                        // without nozzle keys must clear the Project layer.
                        for (const char *key : {"nozzle_volume_type", "extruder_nozzle_stats", "extruder_nozzle_stats_new",
                                                "extruder_nozzle_count", "extruder_nozzle_volume_type", "extruder_nozzle_diameter",
                                                "extruder_nozzle_slot"})
                            if (config_loaded.has(key))
                                file_nozzle_keys.apply_only(config_loaded, {key});

                        config.apply(static_cast<const ConfigBase &>(FullPrintConfig::defaults()));
                        // and place the loaded config over the base.
                        config += std::move(config_loaded);
                        std::map<std::string, std::string> validity = config.validate();
                        if (!validity.empty()) {
                            BOOST_LOG_TRIVIAL(info) << boost::format("Param values in 3mf error: ");
                            for (std::map<std::string, std::string>::iterator it=validity.begin(); it!=validity.end(); ++it)
                                BOOST_LOG_TRIVIAL(info) << boost::format("%1%: %2%")%it->first %it->second;
                            //
                            NotificationManager *notify_manager = q->get_notification_manager();
                            std::string error_message = L("Invalid values found in the 3mf:");
                            error_message += "\n";
                            for (std::map<std::string, std::string>::iterator it=validity.begin(); it!=validity.end(); ++it)
                                error_message += "-" + it->first + ": " + it->second + "\n";
                            error_message += "\n";
                            error_message += L("Please correct them in the param tabs");
                            notify_manager->bbl_show_3mf_warn_notification(error_message);
                        }
                    }
                    if (!config_substitutions.empty()) show_substitutions_info(config_substitutions.substitutions, filename.string());

                    // BBS
                    if (load_model && !load_config) {
                        ;
                    }
                    else {
                        this->model.plates_custom_gcodes = model.plates_custom_gcodes;
                        this->model.design_info = model.design_info;
                        this->model.model_info = model.model_info;
                    }
                }

                if (load_config) {
                    if (!config.empty()) {
                        Preset::normalize(config);
                        PresetBundle *preset_bundle = wxGetApp().preset_bundle;

                        {
                            // BBS: modify the prime tower params for old version file
                            Semver old_version3(2, 0, 0);
                            if (en_3mf_file_type == En3mfType::From_BBS && file_version < old_version3) {
                                double old_filament_prime_volume = 0.;
                                int    filament_count            = 0;
                                {
                                    ConfigOptionFloats  *filament_prime_volume_option = config.option<ConfigOptionFloats>("filament_prime_volume");
                                    ConfigOptionStrings *filament_colors_option       = config.option<ConfigOptionStrings>("filament_colour", true);
                                    filament_count                                    = filament_colors_option->values.size();
                                    if (filament_prime_volume_option) {
                                        std::vector<double> &filament_prime_volume_values = filament_prime_volume_option->values;
                                        if (!filament_prime_volume_values.empty()) {
                                            old_filament_prime_volume = filament_prime_volume_values[0];
                                            if (filament_count > 1) filament_prime_volume_values.resize(filament_count, old_filament_prime_volume);
                                        }
                                    }
                                }
                                ConfigOptionBool *prime_tower_rib_wall_option = config.option<ConfigOptionBool>("prime_tower_rib_wall", true);
                                prime_tower_rib_wall_option->value            = false;

                                ConfigOptionPercent *prime_tower_infill_gap_option = config.option<ConfigOptionPercent>("prime_tower_infill_gap", true);
                                prime_tower_infill_gap_option->value               = 100;

                                ConfigOptionInts *filament_adhesiveness_category_option = config.option<ConfigOptionInts>("filament_adhesiveness_category", true);
                                std::vector<int> &filament_adhesiveness_category_values = filament_adhesiveness_category_option->values;
                                filament_adhesiveness_category_values.resize(filament_count);
                                for (int index = 0; index < filament_count; index++)
                                    filament_adhesiveness_category_values[index] = 100;

                                ConfigOptionFloats *filament_prime_volume_option = config.option<ConfigOptionFloats>("filament_prime_volume", true);

                                std::vector<double> &filament_prime_volume_values = filament_prime_volume_option->values;
                                filament_prime_volume_values.resize(filament_count);
                                for (int index = 0; index < filament_count; index++) {
                                    if (old_filament_prime_volume != 0.)
                                        filament_prime_volume_values[index] = old_filament_prime_volume;
                                    else
                                        filament_prime_volume_values[index] = filament_prime_volume_values[0];
                                }

                                std::vector<std::string> &diff_settings = config.option<ConfigOptionStrings>("different_settings_to_system", true)->values;
                                diff_settings.resize(filament_count + 2);

                                std::vector<std::string> diff_process_keys;
                                std::string              diff_process_settings = diff_settings[0];
                                Slic3r::unescape_strings_cstyle(diff_process_settings, diff_process_keys);
                                diff_process_keys.emplace_back("prime_tower_rib_wall");
                                diff_process_keys.emplace_back("prime_tower_infill_gap");
                                diff_process_settings = Slic3r::escape_strings_cstyle(diff_process_keys);
                                diff_settings[0] = diff_process_settings;

                                for (int index = 0; index < filament_count; index++) {
                                    std::vector<std::string> diff_filament_keys;
                                    std::string              diff_filament_settings = diff_settings[index + 1];
                                    Slic3r::unescape_strings_cstyle(diff_filament_settings, diff_filament_keys);
                                    diff_filament_keys.emplace_back("filament_prime_volume");
                                    diff_filament_keys.emplace_back("filament_adhesiveness_category");
                                    diff_filament_settings   = Slic3r::escape_strings_cstyle(diff_filament_keys);
                                    diff_settings[index + 1] = diff_filament_settings;
                                }
                            }
                        }

                        auto choise = wxGetApp().app_config->get("no_warn_when_modified_gcodes");
                        if (choise.empty() || choise != "true") {
                            // BBS: first validate the printer
                            // validate the system profiles
                            std::set<std::string> modified_gcodes;
                            int validated = preset_bundle->validate_presets(filename.string(), config, modified_gcodes);
                            if (validated == VALIDATE_PRESETS_MODIFIED_GCODES) {
                                std::string warning_message;
                                warning_message += "\n";
                                for (std::set<std::string>::iterator it=modified_gcodes.begin(); it!=modified_gcodes.end(); ++it)
                                    warning_message += "-" + *it + "\n";
                                warning_message += "\n";
                                //show_info(q, _L("The 3mf has following modified G-codes in filament or printer presets:") + warning_message+ _L("Please confirm that these modified G-codes are safe to prevent any damage to the machine!"), _L("Modified G-codes"));

                                MessageDialog dlg(q, _L("The 3mf has following modified G-codes in filament or printer presets:") + warning_message+ _L("Please confirm that these modified G-codes are safe to prevent any damage to the machine!"), _L("Modified G-codes"));
                                dlg.show_dsa_button();
                                auto  res = dlg.ShowModal();
                                if (dlg.get_checkbox_state())
                                    wxGetApp().app_config->set("no_warn_when_modified_gcodes", "true");
                            }
                            else if ((validated == VALIDATE_PRESETS_PRINTER_NOT_FOUND) || (validated == VALIDATE_PRESETS_FILAMENTS_NOT_FOUND)) {
                                std::string warning_message;
                                warning_message += "\n";
                                for (std::set<std::string>::iterator it=modified_gcodes.begin(); it!=modified_gcodes.end(); ++it)
                                    warning_message += "-" + *it + "\n";
                                warning_message += "\n";
                                //show_info(q, _L("The 3mf has following customized filament or printer presets:") + warning_message + _L("Please confirm that the G-codes within these presets are safe to prevent any damage to the machine!"), _L("Customized Preset"));
                                MessageDialog dlg(q, _L("The 3mf has following customized filament or printer presets:") + from_u8(warning_message)+ _L("Please confirm that the G-codes within these presets are safe to prevent any damage to the machine!"), _L("Customized Preset"));
                                dlg.show_dsa_button();
                                auto  res = dlg.ShowModal();
                                if (dlg.get_checkbox_state())
                                    wxGetApp().app_config->set("no_warn_when_modified_gcodes", "true");
                            }
                        }

                        //always load config
                        {
                            // 避免在导入gcode的过程中触发各类流量切换的逻辑

                            this->q->m_loading_project = true;
                            // BBS: save the wipe tower pos in file here, will be used later
                            ConfigOptionFloats* wipe_tower_x_opt = config.opt<ConfigOptionFloats>("wipe_tower_x");
                            ConfigOptionFloats* wipe_tower_y_opt = config.opt<ConfigOptionFloats>("wipe_tower_y");
                            std::optional<ConfigOptionFloats>file_wipe_tower_x;
                            std::optional<ConfigOptionFloats>file_wipe_tower_y;
                            std::optional<ConfigOptionStrings> file_selected_nozzle_diameters;
                            if (wipe_tower_x_opt)
                                file_wipe_tower_x = *wipe_tower_x_opt;
                            if (wipe_tower_y_opt)
                                file_wipe_tower_y = *wipe_tower_y_opt;
                            if (auto *selected_opt = config.opt<ConfigOptionStrings>("filament_diameter_map"))
                                file_selected_nozzle_diameters = *selected_opt;
                            // Same gate as collect / save: leftover maps on a non-rack printer (H2D)
                            // must not revive multi-diameter, whether the 3mf stored the flag or we
                            // would infer it from filament_diameter_map having more than one value.
                            const bool file_has_rack = is_single_ext_multi_nozzle(config);
                            const bool inferred_multi_nozzle_diameter_mode =
                                !loaded_multi_nozzle_diameter_mode.has_value() &&
                                file_has_rack &&
                                infer_multi_nozzle_diameter_mode(config);
                            const bool file_multi_nozzle_diameter_mode =
                                file_has_rack &&
                                loaded_multi_nozzle_diameter_mode.value_or(inferred_multi_nozzle_diameter_mode);
                            BOOST_LOG_TRIVIAL(info)
                                << "multi-diameter project load: resolved mode="
                                << file_multi_nozzle_diameter_mode
                                << ", inferred=" << inferred_multi_nozzle_diameter_mode
                                << ", file_has_rack=" << file_has_rack;

                            preset_bundle->load_config_model(filename.string(), std::move(config), file_version);
                            // The file's printer is selected now. Resolve its nozzles before the presets reload, so
                            // no reader sees the previous printer's nozzles; the mode is restored again below.
                            preset_bundle->project_config.opt<ConfigOptionBool>("multi_nozzle_diameter_mode", true)->value =
                                file_multi_nozzle_diameter_mode;
                            preset_bundle->nozzle_inventory.open_project(preset_bundle->printers, file_nozzle_keys);

                            ConfigOption* bed_type_opt = preset_bundle->project_config.option("curr_bed_type");
                            if (bed_type_opt != nullptr) {
                                BedType bed_type = (BedType)bed_type_opt->getInt();
                                // update app config for bed type
                                bool is_bbl_preset = preset_bundle->printers.get_edited_preset().is_bbl_vendor_preset(&(*preset_bundle));
                                if (is_bbl_preset) {
                                    AppConfig* app_config = wxGetApp().app_config;
                                    if (app_config)
                                        app_config->set("curr_bed_type", std::to_string(int(bed_type)));
                                }
                                q->on_bed_type_change(bed_type, (boost::algorithm::ends_with(filename.string(), ".gcode.3mf") ||
                                                                 boost::algorithm::ends_with(filename.string(), ".gcode")) ?
                                                                    true :
                                                                    false);
                            }

                            // BBS: moved this logic to presetcollection
                            //{
                            //    // After loading of the presets from project, check if they are visible.
                            //    // Set them to visible if they are not.

                            //    auto update_selected_preset_visibility = [](PresetCollection& presets, std::vector<std::string>& names) {
                            //        if (!presets.get_selected_preset().is_visible) {
                            //            assert(presets.get_selected_preset().name == presets.get_edited_preset().name);
                            //            presets.get_selected_preset().is_visible = true;
                            //            presets.get_edited_preset().is_visible = true;
                            //            names.emplace_back(presets.get_selected_preset().name);
                            //        }
                            //    };

                            //    std::vector<std::string> names;
                            //    if (printer_technology == ptFFF) {
                            //        update_selected_preset_visibility(preset_bundle->prints, names);
                            //        for (const std::string& filament : preset_bundle->filament_presets) {
                            //            Preset* preset = preset_bundle->filaments.find_preset(filament);
                            //            if (preset && !preset->is_visible) {
                            //                preset->is_visible = true;
                            //                names.emplace_back(preset->name);
                            //                if (preset->name == preset_bundle->filaments.get_edited_preset().name)
                            //                    preset_bundle->filaments.get_selected_preset().is_visible = true;
                            //            }
                            //        }
                            //    }
                            //    else {
                            //        update_selected_preset_visibility(preset_bundle->sla_prints, names);
                            //        update_selected_preset_visibility(preset_bundle->sla_materials, names);
                            //    }
                            //    update_selected_preset_visibility(preset_bundle->printers, names);

                            //    preset_bundle->update_compatible(PresetSelectCompatibleType::Never);

                            //    // show notification about temporarily installed presets
                            //    if (!names.empty()) {
                            //        std::string notif_text = into_u8(_L_PLURAL("The preset below was temporarily installed on the active instance of PrusaSlicer",
                            //                                                   "The presets below were temporarily installed on the active instance of PrusaSlicer",
                            //                                                   names.size())) + ":";
                            //        for (std::string& name : names)
                            //            notif_text += "\n - " + name;
                            //        notification_manager->push_notification(NotificationType::CustomNotification,
                            //            NotificationManager::NotificationLevel::PrintInfoNotificationLevel, notif_text);
                            //    }
                            //}

                            // BBS
                            // if (printer_technology == ptFFF)
                            //    CustomGCode::update_custom_gcode_per_print_z_from_config(model.custom_gcode_per_print_z, &preset_bundle->project_config);

                            // For exporting from the amf/3mf we shouldn't check printer_presets for the containing information about "Print Host upload"
                            // BBS: add preset combo box re-active logic
                            // currently found only needs re-active here
                            wxGetApp().load_current_presets(false, false);
                            // Update filament colors for the MM-printer profile in the full config
                            // to avoid black (default) colors for Extruders in the ObjectList,
                            // when for extruder colors are used filament colors
                            q->on_filament_count_change(preset_bundle->filament_presets.size());
                            is_project_file = true;

                            DynamicConfig& proj_cfg = preset_bundle->project_config;
                            proj_cfg.opt<ConfigOptionBool>("multi_nozzle_diameter_mode", true)->value =
                                file_multi_nozzle_diameter_mode;
                            BOOST_LOG_TRIVIAL(info)
                                << "multi-diameter project load: restored project mode="
                                << multi_nozzle_diameter_mode_enabled(proj_cfg);
                            // do some post process after loading config
                            {
                                // disable dynamic filament by default, enable when a supported machine is connected
                                auto* dynamic_filament = proj_cfg.option<ConfigOptionBool>("enable_filament_dynamic_map");
                                if(dynamic_filament) dynamic_filament->value = false;

                                auto* has_switcher = proj_cfg.option<ConfigOptionBool>("has_filament_switcher");
                                if(has_switcher) has_switcher->value = false;

                                if (file_selected_nozzle_diameters)
                                    *proj_cfg.opt<ConfigOptionStrings>("filament_diameter_map", true) =
                                        *file_selected_nozzle_diameters;
                                preset_bundle->validate_filament_nozzle_diameter_selections();
                                // Plates are already loaded. A file saved on a multi-nozzle machine can
                                // still spell custom grouping as Nozzle Manual; fold that back to Manual
                                // once the loaded printer cannot host it.
                                sync_custom_map_mode_with_diameter_mode();
                                //BBS: rewrite wipe tower pos stored in 3mf file , the code above should be seriously reconsidered
                                 ConfigOptionFloats* wipe_tower_x = proj_cfg.opt<ConfigOptionFloats>("wipe_tower_x");
                                ConfigOptionFloats* wipe_tower_y = proj_cfg.opt<ConfigOptionFloats>("wipe_tower_y");
                                if (file_wipe_tower_x)
                                    *wipe_tower_x = *file_wipe_tower_x;
                                if (file_wipe_tower_y)
                                    *wipe_tower_y = *file_wipe_tower_y;

                                // Re-clamp restored 3mf tower positions to the current plate; the placed-flag
                                // decision is deferred until filament/nozzle sync finishes below.
                                {
                                    PartPlateList& plate_list = this->partplate_list;
                                    for (size_t plate_id = 0; plate_id < plate_list.get_plate_list().size(); ++plate_id)
                                        plate_list.set_default_wipe_tower_pos_for_plate((int)plate_id, /*init_pos=*/false, /*keep_existing=*/true);
                                }

                                ConfigOptionStrings* filament_color = proj_cfg.opt<ConfigOptionStrings>("filament_colour");
                                if (filament_color) {
                                    size_t filament_count = filament_color->size();

                                    // Sync filament map
                                    ConfigOptionInts* filament_map = proj_cfg.opt<ConfigOptionInts>("filament_map", true);
                                    if (filament_map->size() != filament_count) {
                                        filament_map->values.resize(filament_count, 1);
                                    }

                                    ConfigOptionInts* filament_nozzle_map = proj_cfg.opt<ConfigOptionInts>("filament_nozzle_map", true);
                                    if(filament_nozzle_map->size() != filament_count){
                                        filament_nozzle_map->values.resize(filament_count,0);
                                    }

                                    ConfigOptionInts* filament_volume_map = proj_cfg.opt<ConfigOptionInts>("filament_volume_map", true);
                                    if(filament_volume_map->size() != filament_count){
                                        filament_volume_map->values.resize(filament_count,static_cast<int>(NozzleVolumeType::nvtStandard));
                                    }

                                    // Sync filament multi colour
                                    ConfigOptionStrings* filament_multi_color = proj_cfg.opt<ConfigOptionStrings>("filament_multi_colour", true);
                                    if (filament_multi_color->size() != filament_count) {
                                        filament_multi_color->values.resize(filament_count);
                                    }
                                    // If there is no multi-color data or color is not match, use single color as default value
                                    for (size_t i = 0; i < filament_count; i++) {
                                        std::vector<std::string> colors = Slic3r::split_string(filament_multi_color->values[i], ' ');
                                        if (i >= filament_multi_color->values.size() || colors.empty() || colors[0] != filament_color->values[i] ) {
                                            filament_multi_color->values[i] = filament_color->values[i];
                                        }
                                    }
                                    // Sync filament colour type
                                    ConfigOptionStrings* filament_color_type = proj_cfg.opt<ConfigOptionStrings>("filament_colour_type", true);
                                    if (filament_color_type && filament_color_type->size() != filament_count) {
                                        filament_color_type->values.resize(filament_count);

                                        for (size_t i = 0; i < filament_count; i++) {
                                            if (i >= filament_color_type->values.size() || filament_color_type->values[i].empty()) {
                                                filament_color_type->values[i] = "1";
                                            }
                                        }
                                    }

                                    // Old projects may use HSV-set first color as main; align to JSON[0].
                                    Slic3r::align_project_filament_primary_colors_with_json(preset_bundle);
                                    // Align only wrote project_config; object GLVolumes read p->config
                                    // (filled earlier by on_filament_count_change). Sync before load_model_objects.
                                    q->update_filament_colors_in_full_config();
                                }
                            }
                            // BBS multi-diameter: the project nozzle state has just been loaded. Recompute filament
                            // compatibility before refreshing the selectors so sibling nozzle-diameter
                            // filament presets stay visible for mixed-diameter projects.
                            preset_bundle->update_compatible(PresetSelectCompatibleType::Never);
                            // Update filament combobox after loading config
                            wxGetApp().plater()->sidebar().update_presets(Preset::TYPE_PRINTER);
                            wxGetApp().plater()->sidebar().sync_multi_nozzle_mode_from_project();
                            wxGetApp().plater()->sidebar().update_presets(Preset::TYPE_FILAMENT);
                            // update nozzle count display after loading
                            for (int extruder_id = 0; extruder_id < preset_bundle->nozzle_inventory.extruder_count(); ++extruder_id)
                                updateNozzleCountDisplay(preset_bundle, extruder_id, preset_bundle->nozzle_inventory.volume_type(extruder_id));
                            // The placed-flag decision and clearing m_loading_project are deferred until
                            // after load_model_objects() below actually attaches objects to plates.
                        }
                    }
                    if (!silence) wxGetApp().app_config->update_config_dir(path.parent_path().string());
                }
            } else {
                // BBS: add plate data related logic
                PlateDataPtrs plate_data;
                // BBS: project embedded settings
                std::vector<Preset *> project_presets;
                bool                  is_xxx;
                Semver                file_version;

                if (type_step) {
                        double linear = string_to_double_decimal_point(wxGetApp().app_config->get("linear_defletion"));
                        if (linear <= 0) linear = 0.003;
                        double angle = string_to_double_decimal_point(wxGetApp().app_config->get("angle_defletion"));
                        if (angle <= 0) angle = 0.5;
                        bool split_compound = wxGetApp().app_config->get_bool("is_split_compound");
                        model = Slic3r::Model:: read_from_step(path.string(), strategy,
                        [this, &dlg, real_filename, &progress_percent, &file_percent, step_percent, input_files_ratio, total_files, i](int load_stage, int current, int total, bool &cancel)
                        {
                                bool     cont = true;
                                float percent_float = (100.0f * (float)i / (float)total_files) + input_files_ratio * ((float)step_percent[load_stage] + (float)current * (float)(step_percent[load_stage + 1] - step_percent[load_stage]) / (float)total) / (float)total_files;
                                BOOST_LOG_TRIVIAL(trace) << "load_step_file: percent(float)=" << percent_float << ", stage = " << load_stage << ", curr = " << current << ", total = " << total;
                                progress_percent = (int)percent_float;
                                wxString msg  = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                                cont          = dlg.Update(progress_percent, msg);
                                cancel        = !cont;
                        },
                        [](int isUtf8StepFile) {
                            if (!isUtf8StepFile)
                                Slic3r::GUI::show_info(nullptr, _L("Name of components inside step file is not UTF8 format!") + "\n\n" + _L("The name may show garbage characters!"),
                                                    _L("Attention!"));
                        },
                        [this, &path, &is_user_cancel, &linear, &angle, &split_compound](Slic3r::Step& file, double& linear_value, double& angle_value, bool& is_split)-> int {
                            if (wxGetApp().app_config->get_bool("enable_step_mesh_setting")) {
                                StepMeshDialog mesh_dlg(nullptr, file, linear, angle);
                                if (mesh_dlg.ShowModal() == wxID_OK) {
                                    linear_value = mesh_dlg.get_linear_defletion();
                                    angle_value  = mesh_dlg.get_angle_defletion();
                                    is_split     = mesh_dlg.get_split_compound_value();
                                    return 1;
                                }
                            }else {
                                linear_value = linear;
                                angle_value = angle;
                                is_split = split_compound;
                                return 1;
                            }
                            is_user_cancel = true;
                            return -1;
                        }, linear, angle, split_compound,
                        [](const std::vector<std::string>& names) {
                            wxString msg = _L("The following shells are not closed and may cause issues:") + "\n\n";
                            for (const auto& name : names) {
                                msg += wxString::FromUTF8(name) + "\n";
                            }
                            Slic3r::GUI::show_info(nullptr, msg, _L("Unclosed Shell Warning"));
                        });
                }else {
                    if (boost::algorithm::iends_with(path.string(), ".obj")) {
                        is_xxx = GUI::wxGetApp().app_config->get_bool("gamma_correct_in_import_obj");
                    }
                    model = Slic3r::Model:: read_from_file(
                    path.string(), nullptr, nullptr, strategy, &plate_data, &project_presets, &is_xxx, &file_version, nullptr,
                    [this, &dlg, real_filename, &progress_percent, &file_percent, input_files_ratio, total_files, i, &designer_model_id, &designer_country_code, &makerlab_region, &makerlab_name, &makerlab_id](int current, int total, bool &cancel,
                        std::string &mode_id, std::string &code, std::string &ml_region,  std::string &ml_name, std::string &ml_id)
                    {
                            designer_model_id       = mode_id;
                            designer_country_code   = code;
                            makerlab_region         = ml_region;
                            makerlab_name           = ml_name;
                            makerlab_id             = ml_id;

                            bool     cont = true;
                            float percent_float = (100.0f * (float)i / (float)total_files) + input_files_ratio * 100.0f * ((float)current / (float)total) / (float)total_files;
                            BOOST_LOG_TRIVIAL(trace) << "load_stl_file: percent(float)=" << percent_float << ", curr = " << current << ", total = " << total;
                            progress_percent = (int)percent_float;
                            wxString msg  = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                            cont          = dlg.Update(progress_percent, msg);
                            cancel        = !cont;
                    },
                    nullptr, 0);
                }

                if (designer_model_id.empty() && boost::algorithm::iends_with(path.string(), ".stl")) {
                    read_binary_stl(path.string(), designer_model_id, designer_country_code, makerlab_name, makerlab_region, makerlab_id);
                }

                if (type_any_amf && is_xxx) imperial_units = true;

                for (auto obj : model.objects)
                    if (obj->name.empty()) obj->name = fs::path(obj->input_file).filename().string();

                if (plate_data.size() > 0) {
                    partplate_list.load_from_3mf_structure(plate_data, project_filament_count);
                    partplate_list.update_slice_context_to_current_plate(background_process);
                    this->preview->update_gcode_result(partplate_list.get_current_slice_result());
                    release_PlateData_list(plate_data);
                    sidebar->obj_list()->reload_all_plates();
                }

                // BBS:: project embedded presets
                if (project_presets.size() > 0) {
                    // load project embedded presets
                    PresetsConfigSubstitutions preset_substitutions;
                    PresetBundle &             preset_bundle = *wxGetApp().preset_bundle;
                    preset_substitutions                     = preset_bundle.load_project_embedded_presets(project_presets, ForwardCompatibilitySubstitutionRule::Enable);
                    if (!preset_substitutions.empty()) show_substitutions_info(preset_substitutions);

                    for (unsigned int i = 0; i < project_presets.size(); i++) { delete project_presets[i]; }
                    project_presets.clear();
                }
            }
        } catch (const ConfigurationError &e) {
            std::string message = GUI::format(_L("Failed loading file \"%1%\". An invalid configuration was found."), filename.string()) + "\n\n" + e.what();
            GUI::show_error(q, message);
            continue;
        } catch (const std::exception &e) {
            if (!is_user_cancel)
                GUI::show_error(q, e.what());
            continue;
        }

        progress_percent = 100.0f * (float)i / (float)total_files + init_model_ratio * 100.0f / (float)total_files;
        dlg_cont = dlg.Update(progress_percent);
        if (!dlg_cont) {
            q->skip_thumbnail_invalid = false;
            return empty_result;
        }

        if (load_model) {
            // The model should now be initialized
            auto convert_from_imperial_units = [](Model &model, bool only_small_volumes) { model.convert_from_imperial_units(only_small_volumes); };

            // BBS: add load_old_project logic
            int deleted_objects = 0;
            if ((!is_project_file) && (!load_old_project)) {
                // if (!is_project_file) {
                deleted_objects = model.removed_objects_with_zero_volume();
                if (deleted_objects > 0 && model.objects.empty()) {
                    // GLB / glTF / FBX may have produced a textured ModelObject via
                    // add_textured_mesh_to_model(). When that single object gets
                    // removed (e.g. non-watertight surface whose signed volume
                    // integrates to ~0), drop model.texture_mesh as well so the
                    // texture-import dialog does not pop up over an empty model.
                    model.texture_mesh.reset();
                }
                if (imperial_units)
                    // Convert even if the object is big.
                    convert_from_imperial_units(model, false);
                // A 3MF with a unit was already converted by the reader. Without one, guess from the
                // total volume and scale all objects together, so thin parts keep their size and place.
                else if (type_3mf) {
                    if (!has_3mf_unit) {
                        double total_volume = 0.;
                        for (const ModelObject *object : model.objects)
                            total_volume += object->get_object_stl_stats().volume;
                        // Same thresholds as Model::looks_like_saved_in_meters() / looks_like_imperial_units().
                        double scale = 1.;
                        if (total_volume < 0.008) {
                            BOOST_LOG_TRIVIAL(warning) << "3mf without unit seems in meter units, convert to millimeters:" << filename;
                            model.convert_from_meters(false);
                            scale = 1000.;
                        } else if (total_volume < 8.) {
                            BOOST_LOG_TRIVIAL(warning) << "3mf without unit seems in imperial units, convert to millimeters:" << filename;
                            convert_from_imperial_units(model, false);
                            scale = 25.4;
                        }
                        if (scale != 1.)
                            for (ModelObject *object : model.objects)
                                for (ModelInstance *instance : object->instances)
                                    instance->set_offset(instance->get_offset() * scale);
                    }
                } else if (model.looks_like_saved_in_meters()) {
                    BOOST_LOG_TRIVIAL(warning) << "object loaded seems in meter units, convert to millimeters:" << filename;
                    model.convert_from_meters(true);
                } else if (model.looks_like_imperial_units()) {
                    BOOST_LOG_TRIVIAL(warning) << "object loaded seems in imperial units, convert to millimeters:" << filename;
                    convert_from_imperial_units(model, true);
                }
                // else if (model.looks_like_imperial_units()) {
                // BBS do not handle look like in imperial
                // auto convert_model_if = [convert_from_imperial_units](Model& model, bool condition) {
                //    if (condition)
                //        //FIXME up-scale only the small parts?
                //        convert_from_imperial_units(model, true);
                //};
                // if (answer_convert_from_imperial_units == wxOK_DEFAULT) {
                //    RichMessageDialog dlg(q, format_wxstr(_L_PLURAL(
                //        "The dimensions of the object from file %s seem to be defined in inches.\n"
                //        "The internal unit of PrusaSlicer is a millimeter. Do you want to recalculate the dimensions of the object?",
                //        "The dimensions of some objects from file %s seem to be defined in inches.\n"
                //        "The internal unit of PrusaSlicer is a millimeter. Do you want to recalculate the dimensions of these objects?", model.objects.size()), from_path(filename))
                //        + "\n", _L("The object is too small"), wxICON_QUESTION | wxYES_NO);
                //    dlg.ShowCheckBox(_L("Apply to all the remaining small objects being loaded."));
                //    int answer = dlg.ShowModal();
                //    if (dlg.IsCheckBoxChecked())
                //        answer_convert_from_imperial_units = answer;
                //    else
                //        convert_model_if(model, answer == wxID_YES);
                //}
                // convert_model_if(model, answer_convert_from_imperial_units == wxID_YES);
            }

            // Build the standard 3MF color preview mesh after zero-volume parts have been removed,
            // so deleted parts do not contribute colors, extruders, or bounding-box offsets.
            if (type_3mf && en_3mf_file_type == En3mfType::From_Other && !model.objects.empty()) {
                auto has_painting = [&model]() {
                    for (const ModelObject* object : model.objects)
                        for (const ModelVolume* volume : object->volumes)
                            if (volume->is_model_part() && !volume->mmu_segmentation_facets.empty())
                                return true;
                    return false;
                };
                const bool show_source_warning = wxGetApp().app_config->get_bool("skip_non_bambu_3mf_warning") != true;
                const wxString source_warning = _L("The 3mf is not from Bambu Lab, load geometry data and color data only.");
                auto tex_mesh = std::make_shared<TexturedMesh>();
                bool has_uncolored = false;
                if (!has_painting() && standard_3mf_to_textured_meshes(model, color_group_map, volume_color_data, *tex_mesh, has_uncolored)) {
                    if (show_source_warning)
                        standard_3mf_hint = source_warning + "\n";
                    if (has_3mf_textures)
                        standard_3mf_hint += _L("3MF textures are unsupported and have been discarded.") + " ";
                    if (has_uncolored)
                        standard_3mf_hint += _L("Parts without color will default to gray.") + " ";
                    if (deleted_objects > 0)
                        standard_3mf_hint += _L("Objects with zero volume removed");
                    standard_3mf_hint.Trim();
                    standard_3mf_color_mesh = std::move(tex_mesh);
                    for (ModelObject* object : model.objects) {
                        object->config.erase("extruder");
                        for (ModelVolume* volume : object->volumes)
                            volume->config.erase("extruder");
                    }
                } else {
                    if (show_source_warning) {
                        q->get_notification_manager()->push_notification(NotificationType::CustomNotification,
                            NotificationManager::NotificationLevel::WarningNotificationLevel, into_u8(source_warning));
                    }
                    if (!load_config)
                        add_missing_filaments();
                }
            }

            if (!is_project_file && model.looks_like_multipart_object()) {
                // Load as one object with multiple parts, without asking.
                // convert_multipart_object() clears the model, including texture_mesh.
                model.convert_multipart_object(filaments_cnt);
            }

            // Assign after the merge. Volume ids are copied, so the color bindings
            // captured earlier still match the merged parts.
            if (standard_3mf_color_mesh)
                model.texture_mesh = standard_3mf_color_mesh;
        }
        // else if ((wxGetApp().get_mode() == comSimple) && (type_3mf || type_any_amf) && model_has_advanced_features(model)) {
        //    MessageDialog msg_dlg(q, _L("This file cannot be loaded in a simple mode. Do you want to switch to an advanced mode?")+"\n",
        //        _L("Detected advanced data"), wxICON_WARNING | wxYES | wxNO);
        //    if (msg_dlg.ShowModal() == wxID_YES) {
        //        Slic3r::GUI::wxGetApp().save_mode(comAdvanced);
        //        view3D->set_as_dirty();
        //    }
        //    else
        //        return obj_idxs;
        //}

        progress_percent = 100.0f * (float)i / (float)total_files + center_around_origin_ratio * 100.0f / (float)total_files;
        dlg_cont = dlg.Update(progress_percent);
        if (!dlg_cont) {
            q->skip_thumbnail_invalid = false;
            return empty_result;
        }

        const bool step_subassembly_split = type_step && model.objects.size() > 1;
        std::vector<Vec3d> step_object_position_compensations;
        if (step_subassembly_split) {
            BoundingBoxf3 step_assembly_bbox;
            std::vector<BoundingBoxf3> step_object_bboxes;
            step_object_bboxes.reserve(model.objects.size());
            for (const ModelObject* model_object : model.objects) {
                const BoundingBoxf3 object_bbox = model_object->raw_mesh_bounding_box();
                step_object_bboxes.emplace_back(object_bbox);
                step_assembly_bbox.merge(object_bbox);
            }
            if (step_assembly_bbox.defined) {
                step_object_position_compensations.reserve(step_object_bboxes.size());
                for (const BoundingBoxf3& object_bbox : step_object_bboxes) {
                    Vec3d compensation = Vec3d::Zero();
                    if (object_bbox.defined) {
                        compensation.x() = object_bbox.center().x() - step_assembly_bbox.center().x();
                        compensation.y() = object_bbox.center().y() - step_assembly_bbox.center().y();
                        compensation.z() = object_bbox.min.z() - step_assembly_bbox.min.z();
                    }
                    step_object_position_compensations.emplace_back(compensation);
                }
            }
        }

        auto apply_step_object_position_compensations = [this](const std::vector<size_t>& loaded_idxs, const std::vector<Vec3d>& compensations) {
            if (compensations.empty())
                return false;
            const size_t count = std::min(loaded_idxs.size(), compensations.size());
            if (count == 0)
                return false;

            ModelObject* anchor_object = nullptr;
            for (size_t loaded_idx : loaded_idxs) {
                if (loaded_idx >= q->model().objects.size())
                    continue;
                ModelObject* object = q->model().objects[loaded_idx];
                if (object != nullptr && !object->instances.empty()) {
                    anchor_object = object;
                    break;
                }
            }
            if (anchor_object == nullptr)
                return false;

            const Vec3d anchor_offset = anchor_object->instances.front()->get_offset();
            for (size_t idx = 0; idx < count; ++idx) {
                if (loaded_idxs[idx] >= q->model().objects.size())
                    continue;
                ModelObject* object = q->model().objects[loaded_idxs[idx]];
                if (object == nullptr)
                    continue;

                const Vec3d& compensation = compensations[idx];
                for (ModelInstance* instance : object->instances) {
                    Vec3d offset = instance->get_offset();
                    offset.x() = anchor_offset.x() + compensation.x();
                    offset.y() = anchor_offset.y() + compensation.y();
                    offset.z() += compensation.z();
                    instance->set_offset(offset);
                    instance->set_assemble_transformation(instance->get_transformation());
                }
                // BBS: keep each volume's assemble transformation in sync with its base transformation
                q->ensure_model_object_volume_assemble_initialized(object);
                object->invalidate_bounding_box();
                BOOST_LOG_TRIVIAL(info) << "STEP import: restore sub-assembly relative position for object \""
                                        << object->name << "\", compensation="
                                        << compensation.x() << "," << compensation.y() << "," << compensation.z();
            }
            return count > 0;
        };

        int model_idx = 0;
        for (ModelObject *model_object : model.objects) {
            if (!type_3mf && !type_any_amf)
                model_object->center_around_origin(false);

            // BBS
            BOOST_LOG_TRIVIAL(info) << boost::format("import 3mf IMPORT_LOAD_MODEL_OBJECTS \n");
            wxString msg = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
            model_idx++;
            dlg_cont = dlg.Update(progress_percent, msg);
            if (!dlg_cont) {
                q->skip_thumbnail_invalid = false;
                return empty_result;
            }

            model_object->ensure_on_bed(is_project_file);
        }

        tolal_model_count += model_idx;

        progress_percent = 100.0f * (float)i / (float)total_files + load_model_ratio * 100.0f / (float)total_files;
        dlg_cont = dlg.Update(progress_percent);
        if (!dlg_cont) {
            q->skip_thumbnail_invalid = false;
            return empty_result;
        }
        if (boost::algorithm::iends_with(path.string(), ".stl") || boost::algorithm::iends_with(path.string(), ".obj") ||
            boost::algorithm::iends_with(path.string(), ".glb") || boost::algorithm::iends_with(path.string(), ".gltf") ||
            boost::algorithm::iends_with(path.string(), ".fbx")) {
            import_obj_or_stl = true;
        }
        if (one_by_one) {
            // BBS: add load_old_project logic
            if (type_3mf && !is_project_file && !load_old_project)
                // if (type_3mf && !is_project_file)
                model.center_instances_around_point(this->bed.build_volume().bed_center());
            // BBS: add auxiliary files logic
            // BBS: backup & restore
            if (load_aux) {
                q->model().load_from(model);
                load_auxiliary_files();
            }
            const bool assembly_tree_json_brought_in = !model.get_assembly_tree_json_str().empty();
            if (assembly_tree_json_brought_in)
                q->model().set_assembly_tree_json_str(model.get_assembly_tree_json_str());
            const bool steps_json_brought_in = !model.get_assembly_steps_json_str().empty();
            if (steps_json_brought_in)
                q->model().set_assembly_steps_json_str(model.get_assembly_steps_json_str());
            // Independent assembly object graph (rebuilt lazily on first assembly-view entry, meshes
            // rebound from the prepare model by part_guid). Bridge it like the tree / steps json above.
            if (!model.get_assembly_model_json_str().empty())
                q->model().set_assembly_model_json_str(model.get_assembly_model_json_str());

            TextureImportResult texture_import_result;
            int texture_progress_start = progress_percent;
            int texture_progress_compute_end = progress_percent;
            int texture_progress_object_end = progress_percent;
            int texture_progress_file_end = (int)(100.0f * (float)(i + 1) / (float)total_files);
            if (model.texture_mesh && has_importable_texture(*model.texture_mesh)) {
                texture_progress_start = (int)(100.0f * (float)i / (float)total_files
                                            + load_model_ratio * 100.0f / (float)total_files);
                texture_progress_file_end = (int)(100.0f * (float)(i + 1) / (float)total_files);
                texture_progress_compute_end = texture_progress_start
                    + (texture_progress_file_end - texture_progress_start) * 70 / 100;
                texture_progress_object_end = texture_progress_start
                    + (texture_progress_file_end - texture_progress_start) * 90 / 100;
                wxString texture_msg = wxString::Format(_L("Computing model colors: %s"), from_path(real_filename));
                dlg_cont = dlg.Update(texture_progress_start, texture_msg);
                if (!dlg_cont) {
                    q->skip_thumbnail_invalid = false;
                    return empty_result;
                }

                auto cancel_cb = [&dlg, &dlg_cont]() { return !dlg_cont || dlg.WasCancelled(); };
                auto progress_cb = [&dlg, &dlg_cont, &progress_percent, texture_progress_start, texture_progress_compute_end, texture_msg](int percent) {
                    int mapped_percent = texture_progress_start
                        + (texture_progress_compute_end - texture_progress_start) * std::clamp(percent, 0, 100) / 100;
                    progress_percent = mapped_percent;
                    dlg_cont = dlg.Update(mapped_percent, texture_msg);
                    return dlg_cont;
                };
                auto progress_visibility_cb = [&dlg](bool visible) {
                    dlg.Show(visible);
                    if (visible)
                        dlg.Raise();
                };
                if (!run_textured_mesh_import_dialog(model, texture_import_result, cancel_cb, progress_cb, progress_visibility_cb, standard_3mf_hint)) {
                    q->skip_thumbnail_invalid = false;
                    return empty_result;
                }
                if (texture_import_result.fallback_to_geometry_only && !texture_import_result.fallback_warning.empty()) {
                    MessageDialog(q, texture_import_result.fallback_warning,
                                  _L("Texture Import Warning"),
                                  wxOK | wxICON_WARNING).ShowModal();
                }
            }

            const size_t prev_object_count = q->model().objects.size();
            auto update_import_progress = [&dlg, &progress_percent](int percent, const wxString& msg) {
                progress_percent = percent;
                dlg.Update(percent, msg);
                return true;
            };
            if (!texture_import_result.painted.face_colors.empty()) {
                std::vector<size_t> texture_object_idxs(model.objects.size());
                std::iota(texture_object_idxs.begin(), texture_object_idxs.end(), 0);
                auto apply_progress_cb = [&](int percent, const wxString& msg) {
                    int mapped_percent = texture_progress_compute_end
                        + (texture_progress_object_end - texture_progress_compute_end) * std::clamp(percent, 0, 100) / 100;
                    return update_import_progress(mapped_percent, msg);
                };
                apply_textured_mesh_import_result(model, texture_object_idxs, texture_import_result, apply_progress_cb, false,
                                                  standard_3mf_color_mesh ? &color_group_map : nullptr,
                                                  standard_3mf_color_mesh ? &volume_color_data : nullptr);
                model.add_default_instances();
                model.center_instances_around_point(this->bed.build_volume().bed_center());
                if (!dlg_cont) {
                    q->skip_thumbnail_invalid = false;
                    return empty_result;
                }
            }

            BOOST_LOG_TRIVIAL(info) << boost::format("before load_model_objects, count %1%")%model.objects.size();
            auto object_progress_cb = [&](int percent, const wxString& msg) {
                if (texture_import_result.painted.face_colors.empty())
                    return update_import_progress(progress_percent, msg);
                int mapped_percent = texture_progress_object_end
                    + (texture_progress_file_end - texture_progress_object_end) * std::clamp(percent, 0, 100) / 100;
                return update_import_progress(mapped_percent, msg);
            };
            LoadProgressCallback load_progress_callback;
            if (!texture_import_result.painted.face_colors.empty())
                load_progress_callback = object_progress_cb;
            auto loaded_idxs = load_model_objects(model.objects, is_project_file, false,
                                                  load_progress_callback);
            if (!dlg_cont) {
                q->skip_thumbnail_invalid = false;
                return empty_result;
            }
            {//deal step for assembly_tree
                if (assembly_tree_json_brought_in && prev_object_count == 0) {
                    std::string tree_error;
                    if (!AssemblyTreeData::from_json_string(q->model().get_assembly_tree_json_str(), q->model().get_assembly_tree_data(), &tree_error)) {
                        BOOST_LOG_TRIVIAL(warning) << "failed to restore assembly tree from JSON: " << tree_error;
                    }
                }

                if (steps_json_brought_in) {
                    std::string steps_error;
                    float assembly_part_number_label_font_size = 0.0f;
                    if (!AssemblyStepsTreeData::from_json_string(q->model().get_assembly_steps_json_str(), q->model().get_assembly_steps_tree_data(), q->model(), &steps_error, &assembly_part_number_label_font_size)) {
                        BOOST_LOG_TRIVIAL(warning) << "failed to restore assembly steps tree from JSON: " << steps_error;
                    }
                    if (assembly_part_number_label_font_size > 0.1f && wxGetApp().app_config) {
                        std::ostringstream ss;
                        ss << std::fixed << std::setprecision(2) << assembly_part_number_label_font_size;
                        wxGetApp().app_config->set("assembly_part_number_label_font_size", ss.str());
                    }
                    if (!m_assemble_model_valid)
                        derive_assemble_model();//reload existed 3mf
                }
                // assembly_model.json can arrive without a steps tree. Derive before the prepare
                // view paints its assembly thumbnail, then drop any BVH cached against the
                // not-yet-derived model.
                if (!m_assemble_model_valid && !q->model().get_assembly_model_json_str().empty())
                    derive_assemble_model();
                if (m_assemble_model_valid)
                    partplate_list.reset_thumbnail_assembly_view_data();
                const bool step_position_compensated = apply_step_object_position_compensations(loaded_idxs, step_object_position_compensations);
                bool       need_show_sole_text_notice = false;
                if (type_step && !model.step_import_tree_nodes.empty() && !loaded_idxs.empty()) {
                    BOOST_LOG_TRIVIAL(info) << "STEP import: forward tree to assemble canvas, node_count=" << model.step_import_tree_nodes.size()
                                            << ", loaded_object_count=" << loaded_idxs.size();
                    // A STEP import establishes an assembly structure up front. Capture it into the
                    // independent assembly model BEFORE the prepare-side merge below, so the assembly
                    // model / tree keeps each STEP part as its own object (pre-merge structure).
                    // First STEP: full derive. Later STEPs: the model already exists, so append the
                    // just-loaded (still separate) objects instead of skipping -- otherwise a second STEP
                    // import is never captured and its assembly objects are lost.
                    //
                    // Derive/sync MUST happen before seeding steps. After visiting assemble view the
                    // canvas stays bound to m_assemble_model; new_project clears that model's objects
                    // but leaves the binding. Seeding first would write into an empty model (or into
                    // the prepare model on a cold start) and then be wiped by `m_assemble_model = model`.
                    if (!m_assemble_model_valid)
                        derive_assemble_model();//step import first
                    else
                        sync_assemble_model_on_enter(loaded_idxs);
                    if (GLCanvas3D *assemble_canvas = q->get_assmeble_canvas3D()) {
                        assemble_canvas->set_model(&m_assemble_model);
                        assemble_canvas->append_step_import_to_assembly_tree(model.step_import_tree_nodes, loaded_idxs, model.step_import_path);
                        assemble_canvas->notify_step_import();
                    }
                    // Keep prepare-side JSON/tree in sync so save without re-entering assemble view
                    // still persists the auto-seeded steps.
                    sync_assemble_steps_to_main_model();
                    // Now merge the objects brought in by THIS STEP import into a single multipart object on
                    auto is_split_compound = wxGetApp().app_config->get_bool("is_split_compound");
                    need_show_sole_text_notice = is_split_compound;
                    if (!is_split_compound && loaded_idxs.size() > 1) // Make it more convenient for users
                        wxGetApp().obj_list()->merge_objects(loaded_idxs);
                }
                if (step_position_compensated) {
                    update();
                    for (const size_t idx : loaded_idxs) wxGetApp().obj_list()->update_info_items(idx);
                    object_list_changed();
                }
                if (step_subassembly_split && loaded_idxs.size() > 1 && need_show_sole_text_notice) {
                    q->get_notification_manager()
                        ->bbl_show_sole_text_notification(NotificationType::CustomNotification,
                                                          _u8L("The imported STEP file is split by sub-assembly, so some objects may not be placed on the build plate at first.\n"
                                                               "It is expected if they are placed on the build plate later after move,rotate gizmo or similar operations.\n"
                                                               "The overall assembly can be checked from the assembly thumbnail or by entering the assembly view."),
                                                          true, 0, false);
                }
            }

            obj_idxs.insert(obj_idxs.end(), loaded_idxs.begin(), loaded_idxs.end());
            if (import_obj_or_stl) {
                for (int i = 0; i < loaded_idxs.size(); i++) {
                    q->model().set_assembly_pos(q->model().objects[q->model().objects.size() - 1 - i]);
                }
            }
            BOOST_LOG_TRIVIAL(info) << boost::format("finished load_model_objects");
            if (is_project_file) {
                // First point where objects are actually attached to plates, so the placed-flag
                // decision can be made now. Set it before clearing m_loading_project so any
                // reload_scene() triggered above still saw the flag as unset.
                PartPlateList& plate_list = this->partplate_list;
                for (size_t plate_id = 0; plate_id < plate_list.get_plate_list().size(); ++plate_id)
                    init_wipe_tower_placed_flag(*plate_list.get_plate((int)plate_id));
                this->q->m_loading_project = false;
            }
            wxString msg = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
            dlg_cont     = dlg.Update(progress_percent, msg);
            if (!dlg_cont) {
                q->skip_thumbnail_invalid = false;
                return empty_result;
            }
        } else {
            // This must be an .stl or .obj file, which may contain a maximum of one volume.
            for (const ModelObject *model_object : model.objects) {
                new_model->add_object(*model_object);

                BOOST_LOG_TRIVIAL(debug) << boost::format("added object %1%")%model_object->name;
                wxString msg = wxString::Format(_L("Loading file: %s"), from_path(real_filename));
                dlg_cont     = dlg.Update(progress_percent, msg);
                if (!dlg_cont) {
                    q->skip_thumbnail_invalid = false;
                    return empty_result;
                }
            }
        }
    }

    if (new_model != nullptr && new_model->objects.size() > 1) {
        //BBS do not popup this dialog

        if (ask_multi) {
            MessageDialog msg_dlg(q, _L("Load these files as a single object with multiple parts?\n"), _L("Object with multiple parts was detected"),
                                  wxICON_WARNING | wxYES | wxNO);
            if (msg_dlg.ShowModal() == wxID_YES) { new_model->convert_multipart_object(filaments_cnt); }
        }

        auto loaded_idxs = load_model_objects(new_model->objects);
        obj_idxs.insert(obj_idxs.end(), loaded_idxs.begin(), loaded_idxs.end());
        if (import_obj_or_stl) {
            for (int i = 0; i < loaded_idxs.size(); i++) {
                q->model().set_assembly_pos(q->model().objects[q->model().objects.size() - 1 - i]);
            }
        }
    }


    if (new_model) delete new_model;

    //BBS: translate old 3mf to correct positions
    if (translate_old) {
        //translate the objects
        int plate_count = partplate_list.get_plate_count();
        for (int index = 1; index < plate_count; index ++) {
            PartPlate* cur_plate = (PartPlate *)partplate_list.get_plate(index);

            Vec3d cur_origin = cur_plate->get_origin();
            Vec3d new_origin = partplate_list.compute_origin_using_new_size(index, current_width, current_depth);

            cur_plate->translate_all_instance(new_origin - cur_origin);
        }
        partplate_list.reset_size(current_width, current_depth, current_height, true, true);
    }

    //BBS: add gcode loading logic in the end
    q->m_exported_file = false;
    q->skip_thumbnail_invalid = false;
    if (load_model && load_config) {
        if (model.objects.empty()) {
            partplate_list.load_gcode_files();
            PartPlate * first_plate = nullptr, *cur_plate = nullptr;
            int plate_cnt = partplate_list.get_plate_count();
            int index = 0, first_plate_index = 0;
            q->m_valid_plates_count = 0;
            for (index = 0; index < plate_cnt; index ++)
            {
                cur_plate = partplate_list.get_plate(index);
                if (!first_plate && cur_plate->is_slice_result_valid()) {
                    first_plate = cur_plate;
                    first_plate_index = index;
                }
                if (cur_plate->is_slice_result_valid())
                    q->m_valid_plates_count ++;
            }
            if (first_plate&&first_plate->is_slice_result_valid()) {
                q->m_exported_file = true;
                //select plate 0 as default
                q->select_plate(first_plate_index);
                //set to 3d tab
                q->select_view_3D("Preview");
                wxGetApp().mainframe->select_tab(MainFrame::tpPreview);
            }
            else {
                //set to 3d tab
                q->select_view_3D("3D");
                //select plate 0 as default
                q->select_plate(0);
            }
        }
        else {
            //set to 3d tab
            q->select_view_3D("3D");
            //select plate 0 as default
            q->select_plate(0);
        }
    }
    else {
        //always set to 3D after loading files
        q->select_view_3D("3D");
        wxGetApp().mainframe->select_tab(MainFrame::tp3DEditor);
    }

    if (load_model) {
        if (!silence) wxGetApp().app_config->update_skein_dir(input_files[input_files.size() - 1].parent_path().make_preferred().string());
        // XXX: Plater.pm had @loaded_files, but didn't seem to fill them with the filenames...
    }
    // automatic selection of added objects
    if (!obj_idxs.empty() && view3D != nullptr) {
        // update printable state for new volumes on canvas3D
        wxGetApp().plater()->canvas3D()->update_instance_printable_state_for_objects(obj_idxs);

        if (!load_config) {
            Selection& selection = view3D->get_canvas3d()->get_selection();
            selection.clear();
            for (size_t idx : obj_idxs) {
                selection.add_object((unsigned int)idx, false);
            }
        }
        // BBS: update object list selection
        this->sidebar->obj_list()->update_selections();

        if (view3D->get_canvas3d()->get_gizmos_manager().is_enabled())
            // this is required because the selected object changed and the flatten on face an sla support gizmos need to be updated accordingly
            view3D->get_canvas3d()->update_gizmos_on_off_state();
    }

    GLGizmoSimplify::add_simplify_suggestion_notification(
        obj_idxs, model.objects, *notification_manager);

    //set designer_model_id
    q->model().stl_design_id = designer_model_id;
    q->model().stl_design_country = designer_country_code;
    q->model().makerlab_region = makerlab_region;
    q->model().makerlab_name = makerlab_name;
    q->model().makerlab_id = makerlab_id;

    //if (!designer_model_id.empty() && q->model().stl_design_id.empty() && !designer_country_code.empty()) {
    //    q->model().stl_design_id = designer_model_id;
    //    q->model().stl_design_country = designer_country_code;
    //}
    //else {
    //    q->model().stl_design_id = "";
    //    q->model().stl_design_country = "";
    //}

    if (tolal_model_count <= 0 && !q->m_exported_file) {
        dlg.Hide();
        if (!is_user_cancel) {
            MessageDialog msg(wxGetApp().mainframe, _L("The file does not contain any geometry data."), _L("Warning"), wxYES | wxICON_WARNING);
            if (msg.ShowModal() == wxID_YES) {}
        }
    }
    std::chrono::system_clock::time_point default_time;
    if (start == default_time) {
        start = std::chrono::system_clock::now();
    }
    if (!input_files.empty()) {
        auto path = input_files.front();
        file_type = path.extension().string();

        if (model.model_info == nullptr) {
            is_mw = "false";
        }
        else if(model.model_info->description != "") {
            is_mw = "true";
        }
    }
    q->schedule_background_process(true);
    q->mark_plate_toolbar_image_dirty();
    return obj_idxs;
}

 #define AUTOPLACEMENT_ON_LOAD

std::vector<size_t> Plater::priv::load_model_objects(const ModelObjectPtrs& model_objects, bool allow_negative_z,
                                                     bool split_object, LoadProgressCallback progress_callback)
{
    PERF_TRACE("load_model_objects");
    const Vec3d bed_size = Slic3r::to_3d(this->bed.build_volume().bounding_volume2d().size(), 1.0) - 2.0 * Vec3d::Ones();
    auto update_load_progress = [&progress_callback](int percent, const wxString& message) {
        return !progress_callback || progress_callback(std::clamp(percent, 0, 100), message);
    };

#ifndef AUTOPLACEMENT_ON_LOAD
    // bool need_arrange = false;
#endif /* AUTOPLACEMENT_ON_LOAD */
    bool scaled_down = false;
    std::vector<size_t> obj_idxs;
    unsigned int obj_count = model.objects.size();

#ifdef AUTOPLACEMENT_ON_LOAD
    ModelInstancePtrs new_instances;
#endif /* AUTOPLACEMENT_ON_LOAD */
    if (!update_load_progress(0, _L("Importing model to project...")))
        return obj_idxs;
    for (ModelObject *model_object : model_objects) {
        auto *object = model.add_object(*model_object);
        object->sort_volumes(true);
        std::string object_name = object->name.empty() ? fs::path(object->input_file).filename().string() : object->name;
        obj_idxs.push_back(obj_count++);

        if (model_object->instances.empty()) {
#ifdef AUTOPLACEMENT_ON_LOAD
            object->center_around_origin();
            new_instances.emplace_back(object->add_instance());
#else /* AUTOPLACEMENT_ON_LOAD */
            // if object has no defined position(s) we need to rearrange everything after loading
            // need_arrange = true;
             // add a default instance and center object around origin
            object->center_around_origin();  // also aligns object to Z = 0
            ModelInstance* instance = object->add_instance();

            //BBS calc transformation
            Geometry::Transformation t = instance->get_transformation();
            instance->set_offset(Slic3r::to_3d(this->bed.build_volume().bed_center(), -object->origin_translation(2)));
#endif /* AUTOPLACEMENT_ON_LOAD */
        }

        //BBS: when the object is too large, let the user choose whether to scale it down
        for (size_t i = 0; i < object->instances.size(); ++i) {
            ModelInstance* instance = object->instances[i];
            const Vec3d size = object->instance_bounding_box(i).size();
            const Vec3d ratio = size.cwiseQuotient(bed_size);
            const double max_ratio = std::max(ratio(0), ratio(1));
            if (max_ratio > 10000) {
                MessageDialog dlg(q, _L("Your object appears to be too large, Do you want to scale it down to fit the heat bed automatically?"), _L("Object too large"),
                                  wxICON_QUESTION | wxYES);
                int           answer = dlg.ShowModal();
                // the size of the object is too big -> this could lead to overflow when moving to clipper coordinates,
                // so scale down the mesh
                object->scale_mesh_after_creation(1. / max_ratio);
                object->origin_translation = Vec3d::Zero();
                object->center_around_origin();
                scaled_down = true;
                break;
            }
            else if (max_ratio > 10) {
                MessageDialog dlg(q, _L("Your object appears to be too large, Do you want to scale it down to fit the heat bed automatically?"), _L("Object too large"),
                                  wxICON_QUESTION | wxYES_NO);
                int           answer = dlg.ShowModal();
                if (answer == wxID_YES) {
                    instance->set_scaling_factor(instance->get_scaling_factor() / max_ratio);
                    scaled_down = true;
                }
            }
        }

        object->ensure_on_bed(allow_negative_z);
        if (!update_load_progress(35, _L("Placing model on the bed...")))
            return obj_idxs;
        if (!split_object) {
            //BBS initial assemble transformation
            for (ModelObject* model_object : model.objects) {
                //BBS initialize assemble transformation
                for (int i = 0; i < model_object->instances.size(); i++) {
                    if (!model_object->instances[i]->is_assemble_initialized()) {
                        model_object->instances[i]->set_assemble_transformation(model_object->instances[i]->get_transformation());
                    }
                }
                // BBS: also initialize per-volume assemble transformation so the assembly view can render new volumes correctly even before any explicit per-volume edit.
                q->ensure_model_object_volume_assemble_initialized(model_object);
            }
        }
    }

    BOOST_LOG_TRIVIAL(info) << boost::format("loaded objects, begin to auto placement");
    if (!update_load_progress(55, _L("Placing model on the bed...")))
        return obj_idxs;
#ifdef AUTOPLACEMENT_ON_LOAD
#if 0
    // FIXME distance should be a config value /////////////////////////////////
    auto min_obj_distance = static_cast<coord_t>(6/SCALING_FACTOR);
    const auto *bed_shape_opt = config->opt<ConfigOptionPoints>("printable_area");
    assert(bed_shape_opt);
    auto& bedpoints = bed_shape_opt->values;
    Polyline bed; bed.points.reserve(bedpoints.size());
    for(auto& v : bedpoints) bed.append(Point::new_scale(v(0), v(1)));

    // BBS: get wipe tower of current plate
    int cur_plate_idx = partplate_list.get_curr_plate_index();
    std::pair<bool, GLCanvas3D::WipeTowerInfo> wti = view3D->get_canvas3d()->get_wipe_tower_info(cur_plate_idx);

    arr::find_new_position(model, new_instances, min_obj_distance, bed, wti);

    // it remains to move the wipe tower:
    view3D->get_canvas3d()->arrange_wipe_tower(wti);
#else
    // BBS: find an empty cell to put the copied object
    for (auto& instance : new_instances) {
        auto offset = instance->get_offset();
        auto start_point = this->bed.build_volume().bounding_volume2d().center();
        bool plate_empty = partplate_list.get_curr_plate()->empty();
        Vec3d displacement;
        if (plate_empty)
            displacement = {start_point(0), start_point(1), offset(2)};
        else {
            auto empty_cell = wxGetApp().plater()->canvas3D()->get_nearest_empty_cell({start_point(0), start_point(1)});
            displacement    = {empty_cell.x(), empty_cell.y(), offset(2)};
        }
        instance->set_offset(displacement);
    }
#endif

#endif /* AUTOPLACEMENT_ON_LOAD */

    //BBS: remove the auto scaled_down logic when load models
    //if (scaled_down) {
    //    GUI::show_info(q,
    //        _L("Your object appears to be too large, so it was automatically scaled down to fit your print bed."),
    //        _L("Object too large?"));
    //}

    BOOST_LOG_TRIVIAL(info) << boost::format("finished auto placement, before add_objects_to_list");
    notification_manager->close_notification_of_type(NotificationType::UpdatedItemsInfo);
    if (!update_load_progress(75, _L("Updating object list...")))
        return obj_idxs;

    if (obj_idxs.size() > 1) {
        std::vector<size_t> obj_idxs_1 (obj_idxs.begin(), obj_idxs.end() - 1);

        wxGetApp().obj_list()->add_objects_to_list(obj_idxs_1, false);
        wxGetApp().obj_list()->add_object_to_list(obj_idxs[obj_idxs.size() - 1]);
    }
    else
        wxGetApp().obj_list()->add_objects_to_list(obj_idxs);

    BOOST_LOG_TRIVIAL(info) << boost::format("after add_objects_to_list");
    if (!update_load_progress(90, _L("Updating 3D view...")))
        return obj_idxs;
    {
        PERF_TRACE("Rendering Object loaded");
        update();
    }
    // Update InfoItems in ObjectList after update() to use of a correct value of the GLCanvas3D::is_sinking(),
    // which is updated after a view3D->reload_scene(false, flags & (unsigned int)UpdateParams::FORCE_FULL_SCREEN_REFRESH) call
    for (const size_t idx : obj_idxs)
        wxGetApp().obj_list()->update_info_items(idx);

    object_list_changed();

    this->schedule_background_process();
    update_load_progress(100, _L("Model imported."));

    return obj_idxs;
}

// BBS
void Plater::priv::load_auxiliary_files()
{
    wxLogNull suppress_log;
    std::string auxiliary_path = encode_path(q->model().get_auxiliary_file_temp_path().c_str());
    //wxGetApp().mainframe->m_project->Reload(auxiliary_path);
}

bool Plater::priv::run_textured_mesh_import_dialog(Slic3r::Model& loaded_model, TextureImportResult& result,
                                                   std::function<bool()> cancel_callback,
                                                   std::function<bool(int)> progress_callback,
                                                   std::function<void(bool)> progress_visibility_callback,
                                                   const wxString& hint)
{
    if (!loaded_model.texture_mesh || !has_importable_texture(*loaded_model.texture_mesh)) return false;

    // Defense in depth: if all geometry got dropped earlier (e.g. by a future
    // regression of the zero-volume cleanup) but the textured mesh is still
    // alive, there is nothing for the dialog to paint onto. Skip the dialog
    // gracefully so load_files() can fall through to its "no geometry"
    // message instead of making the user round-trip a meaningless matcher.
    if (loaded_model.objects.empty()) {
        BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: skipping dialog because the loaded model has no geometry objects";
        loaded_model.texture_mesh.reset();
        result.skipped = true;
        return true;
    }

    const wxString fallback_warning = _L("Texture import failed. The model appears to contain texture data, but the texture import process could not be completed. The model will be imported as geometry only.");

    BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: opening texture import dialog";

    std::vector<TextureFilamentEntry> filament_entries;
    {
        auto& preset_bundle = *wxGetApp().preset_bundle;
        auto& project_config = preset_bundle.project_config;
        auto* colours_opt = project_config.option<ConfigOptionStrings>("filament_colour");
        auto* is_mixed_opt = project_config.option<ConfigOptionBools>("filament_is_mixed");
        auto* components_opt = project_config.option<ConfigOptionStrings>("filament_mixed_components");
        auto* ratios_opt = project_config.option<ConfigOptionStrings>("filament_mixed_sublayer_ratios");
        const size_t total = preset_bundle.filament_presets.size();
        auto family_type_of = [&preset_bundle](size_t idx) -> std::string {
            if (idx >= preset_bundle.filament_presets.size())
                return {};
            Preset* preset = preset_bundle.filaments.find_preset(preset_bundle.filament_presets[idx]);
            if (!preset)
                return {};
            std::string display_type;
            return preset->config.get_filament_type(display_type);
        };
        filament_entries.reserve(total);
        for (size_t i = 0; i < total; ++i) {
            TextureFilamentEntry entry;
            entry.kind = (is_mixed_opt && i < is_mixed_opt->values.size() && is_mixed_opt->values[i]) ?
                TextureFilamentKind::ExistingMixed : TextureFilamentKind::ExistingPhysical;
            entry.dialog_index = (int)filament_entries.size();
            entry.project_config_index = i;
            entry.color_hex = (colours_opt && i < colours_opt->values.size()) ? colours_opt->values[i] : "#808080";

            std::string name;
            if (i < preset_bundle.filament_presets.size()) {
                auto* preset = preset_bundle.filaments.find_preset(preset_bundle.filament_presets[i]);
                if (preset)
                    name = preset->label(false);
            }
            if (name.empty())
                name = into_u8(wxString::Format(_L("Filament %d"), (int)i + 1));
            entry.name = name;

            if (entry.kind == TextureFilamentKind::ExistingMixed) {
                if (components_opt && i < components_opt->values.size())
                    entry.mixed_components = Slic3r::parse_mixed_components(components_opt->values[i]);
                std::vector<double> ratios = Slic3r::parse_mixed_ratios(
                    ratios_opt && i < ratios_opt->values.size() ? ratios_opt->values[i] : "",
                    entry.mixed_components.size());
                entry.mixed_ratios.reserve(ratios.size());
                for (double ratio : ratios)
                    entry.mixed_ratios.push_back((int)std::lround(ratio * 100.0));

                std::string ref;
                bool found = false;
                bool mismatch = false;
                for (unsigned int comp : entry.mixed_components) {
                    if (comp < 1)
                        continue;
                    const std::string ft = family_type_of((size_t)comp - 1);
                    if (ft.empty())
                        continue;
                    if (!found) {
                        ref = ft;
                        found = true;
                    } else if (ft != ref) {
                        mismatch = true;
                        break;
                    }
                }
                if (found && !mismatch)
                    entry.type = ref;
                else if (!mismatch) {
                    entry.type = family_type_of(i);
                }
            } else {
                entry.type = family_type_of(i);
            }
            filament_entries.push_back(std::move(entry));
        }
    }

    TextureImportDialog dlg(q, *loaded_model.texture_mesh, filament_entries,
                            std::move(cancel_callback), std::move(progress_callback),
                            std::move(progress_visibility_callback), hint);
    if (dlg.ShowModal() != wxID_OK) {
        if (dlg.was_skipped()) {
            BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: user skipped texture matching";
            result.skipped = true;
            loaded_model.texture_mesh.reset();
            return true;
        }
        if (dlg.fallback_to_geometry_only()) {
            BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: texture import failed, falling back to geometry-only import";
            result.fallback_to_geometry_only = true;
            result.fallback_warning = fallback_warning;
            loaded_model.texture_mesh.reset();
            return true;
        }
        BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: user cancelled";
        loaded_model.texture_mesh.reset();
        return false;
    }

    auto painted = dlg.get_painted_mesh();
    auto final_matches = dlg.get_matches();

    const bool has_unmatched = std::any_of(final_matches.begin(), final_matches.end(),
        [](const Slic3r::FilamentMatch& m) { return m.filament_index < 0; });
    if (has_unmatched) {
        BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: unmatched filaments, aborting apply";
        loaded_model.texture_mesh.reset();
        return false;
    }

    if (painted.face_colors.empty() || final_matches.empty()) {
        BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: no painting result";
        result.fallback_to_geometry_only = true;
        result.fallback_warning = fallback_warning;
        loaded_model.texture_mesh.reset();
        return true;
    }

    BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: got " << painted.cluster_colors.size()
                            << " clusters, skipped=" << dlg.was_skipped();

    result.painted = std::move(painted);
    result.matches = std::move(final_matches);
    result.new_filament_colors = dlg.get_new_filament_colors();
    result.new_filament_preset_names = dlg.get_new_filament_preset_names();
    result.new_mixed_filaments = dlg.get_new_mixed_filaments();
    result.filament_entries = dlg.get_filament_entries();
    result.existing_filament_count = dlg.get_existing_filament_count();
    result.skipped = dlg.was_skipped();
    return true;
}

// A standard 3MF stores an exact color per triangle corner, so the volumes can be painted
// where they are instead of being replaced by the dialog's preview mesh. Objects and parts
// keep the structure the file described; only mmu_segmentation_facets and the part filament
// change. Returns false when nothing could be painted.
static bool paint_standard_3mf_volumes(
    Slic3r::Model&                                 model,
    const std::map<int, std::vector<std::string>>& color_group_map,
    const VolumeColorInfoMap&                      volume_color_data,
    const Slic3r::PaintedMesh&                     painted,
    const std::vector<Slic3r::FilamentMatch>&      matches)
{
    if (painted.cluster_colors.empty() || matches.empty())
        return false;

    std::vector<int> cluster_filaments(painted.cluster_colors.size(), 0);
    for (const auto& match : matches)
        if (match.cluster_index >= 0 && match.cluster_index < (int) cluster_filaments.size() && match.filament_index >= 0)
            cluster_filaments[match.cluster_index] = match.filament_index + 1;

    // The dialog clustered the source palette in color space, so map each source color back
    // to the cluster it landed in and reuse the filament the user picked for that cluster.
    auto source_filament = [&](const std::array<std::size_t, 3>& rgb) {
        auto source = painted.original_color_to_cluster.find(rgb);
        return source != painted.original_color_to_cluster.end() && source->second >= 0 ? cluster_filaments[source->second] : 0;
    };
    // Triangles without usable colors were previewed in the uncolored grey, so they take the
    // filament picked for that grey.
    const int uncolored_filament = source_filament(Slic3r::STANDARD_3MF_UNCOLORED_RGB);

    std::map<std::string, int> color_filament_cache;
    auto filament_for_color = [&](const std::string& color_str) {
        auto cached = color_filament_cache.find(color_str);
        if (cached != color_filament_cache.end())
            return cached->second;
        const RGBA rgba = convert_color_string_to_rgba(color_str);
        std::array<std::size_t, 3> rgb;
        for (int c = 0; c < 3; ++c)
            rgb[c] = static_cast<std::size_t>(std::lround(std::clamp(rgba[c], 0.0f, 1.0f) * 255.0f));
        const int best = source_filament(rgb);
        color_filament_cache.emplace(color_str, best);
        return best;
    };

    auto has_vertex_colors = [&volume_color_data](int volume_id) {
        auto color_info = volume_color_data.find(volume_id);
        if (color_info == volume_color_data.end())
            return false;
        for (const TriangleColor& binding : color_info->second.triangle_colors)
            if (binding.indices[0] != binding.indices[1] || binding.indices[1] != binding.indices[2] ||
                binding.indices[0] != binding.indices[2])
                return true;
        return false;
    };

    auto filament_id_at = [&](int volume_id, int triangle_idx, int corner) {
        int filament_id = uncolored_filament;
        auto color_info = volume_color_data.find(volume_id);
        if (color_info != volume_color_data.end() && triangle_idx >= 0 &&
            triangle_idx < (int) color_info->second.triangle_colors.size()) {
            if (const std::string* color_str = standard_3mf_corner_color(color_group_map, color_info->second,
                                                                         color_info->second.triangle_colors[triangle_idx], corner))
                filament_id = filament_for_color(*color_str);
        }
        return filament_id > 0 ? filament_id : 1;
    };

    // obj_import_color_deal() only checks that this is non-empty when a per-face callback
    // supplies the ids, so pass the filaments the clusters resolved to.
    std::vector<unsigned char> used_filament_ids;
    for (int filament_id : cluster_filaments)
        if (filament_id > 0)
            used_filament_ids.push_back(static_cast<unsigned char>(filament_id));
    if (used_filament_ids.empty())
        return false;

    const bool painted_any = Slic3r::Model::obj_import_color_deal(used_filament_ids, std::nullopt, &model,
                                                                  has_vertex_colors, filament_id_at);

    // Match the textured import: the base filament of a painted part is the lowest filament
    // its paint uses, so the object list agrees with what is painted on the part. A part whose
    // every corner resolves to one filament is solid: it takes that filament and keeps no paint.
    struct PartFilament {
        int  min_filament = -1;
        bool solid        = false;
    };
    auto part_filament = [&](const ModelVolume& volume) {
        PartFilament info;
        const int volume_id = volume.id().id;
        const int face_count = (int) volume.mesh().its.indices.size();
        bool single_filament = true;
        for (int face_idx = 0; face_idx < face_count; ++face_idx)
            for (int corner = 0; corner < 3; ++corner) {
                const int filament_id = filament_id_at(volume_id, face_idx, corner);
                if (info.min_filament > 0 && filament_id != info.min_filament)
                    single_filament = false;
                if (info.min_filament < 0 || filament_id < info.min_filament)
                    info.min_filament = filament_id;
            }
        info.solid = single_filament && info.min_filament > 0;
        return info;
    };

    size_t solid_parts = 0;
    for (ModelObject* object : model.objects) {
        if (object == nullptr)
            continue;
        int object_filament = -1;
        for (ModelVolume* volume : object->volumes) {
            if (volume == nullptr || !volume->is_model_part())
                continue;
            const PartFilament info = part_filament(*volume);
            if (info.min_filament <= 0)
                continue;
            if (info.solid) {
                volume->mmu_segmentation_facets.reset();
                ++solid_parts;
            }
            volume->config.set("extruder", info.min_filament);
            if (object_filament < 0 || info.min_filament < object_filament)
                object_filament = info.min_filament;
        }
        if (object_filament > 0)
            object->config.set("extruder", object_filament);
    }

    BOOST_LOG_TRIVIAL(info) << "painted standard 3mf volumes, solid parts="
                            << solid_parts << ", painted=" << painted_any;
    return painted_any || solid_parts > 0;
}

void Plater::priv::apply_textured_mesh_import_result(Slic3r::Model& loaded_model, const std::vector<size_t>& obj_idxs,
                                                     const TextureImportResult& result,
                                                     LoadProgressCallback progress_callback, bool update_scene,
                                                     const std::map<int, std::vector<std::string>>* standard_3mf_color_groups,
                                                     const VolumeColorInfoMap* standard_3mf_volume_colors)
{
    auto update_apply_progress = [&progress_callback](int percent, const wxString& message) {
        return !progress_callback || progress_callback(std::clamp(percent, 0, 100), message);
    };

    const auto& painted = result.painted;
    const auto& final_matches = result.matches;

    if (painted.face_colors.empty() || final_matches.empty()) {
        BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: no painting result";
        loaded_model.texture_mesh.reset();
        return;
    }

    BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: got " << painted.cluster_colors.size()
                            << " clusters, skipped=" << result.skipped;
    if (!update_apply_progress(0, _L("Applying texture colors...")))
        return;

    auto collect_physical_color_strs = []() {
        std::vector<std::string> colors;
        auto& project_config = wxGetApp().preset_bundle->project_config;
        auto* colours_opt = project_config.option<ConfigOptionStrings>("filament_colour");
        auto* is_mixed_opt = project_config.option<ConfigOptionBools>("filament_is_mixed");
        const size_t total = wxGetApp().preset_bundle->filament_presets.size();
        for (size_t i = 0; i < total; ++i) {
            const bool is_mixed = is_mixed_opt && i < is_mixed_opt->values.size() && is_mixed_opt->values[i];
            if (!is_mixed)
                colors.push_back(colours_opt && i < colours_opt->values.size() ? colours_opt->values[i] : "#808080");
        }
        return colors;
    };

    const auto& entries = result.filament_entries;
    // Final sidebar ordering produced here (ExistingPhysical -> NewPhysical ->
    // ExistingMixed -> NewMixed) MUST stay in sync with
    // TextureImportDialog::compute_display_numbers(), which mirrors this order
    // so the import dialog shows the same IDs the sidebar will show after OK.
    std::vector<int> filament_index_remap(entries.size(), -1);
    size_t new_physical_count = 0;
    for (const auto& entry : entries) {
        if (entry.kind == TextureFilamentKind::NewPhysical)
            ++new_physical_count;
    }

    for (const auto& entry : entries) {
        if (entry.dialog_index < 0 || entry.dialog_index >= (int)filament_index_remap.size())
            continue;
        if (entry.kind == TextureFilamentKind::ExistingPhysical)
            filament_index_remap[entry.dialog_index] = (int)entry.project_config_index;
    }

    std::vector<std::pair<wxColour, std::string>> new_physicals;
    std::vector<int> new_physical_dialog_indices;
    new_physicals.reserve(new_physical_count);
    new_physical_dialog_indices.reserve(new_physical_count);
    for (const auto& entry : entries) {
        if (entry.kind != TextureFilamentKind::NewPhysical)
            continue;
        new_physicals.emplace_back(wxColour(entry.color_hex), entry.preset_name);
        new_physical_dialog_indices.push_back(entry.dialog_index);
    }
    size_t added_physical = 0;
    if (!new_physicals.empty()) {
        const size_t insert_pos = sidebar->add_custom_filaments(new_physicals);
        added_physical = (insert_pos == size_t(-1)) ? 0 :
            std::min(new_physicals.size(), sidebar->combos_filament().size() - insert_pos);
        for (size_t i = 0; i < added_physical; ++i) {
            const int dialog_index = new_physical_dialog_indices[i];
            const size_t final_idx = insert_pos + i;
            if (dialog_index >= 0 && dialog_index < (int)filament_index_remap.size())
                filament_index_remap[dialog_index] = (int)final_idx;
            BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: created pending physical filament dialog="
                                    << dialog_index << " final=" << final_idx
                                    << " color=" << new_physicals[i].first.GetAsString(wxC2S_HTML_SYNTAX)
                                    << " preset=" << new_physicals[i].second;
        }
    }
    for (const auto& entry : entries) {
        if (entry.dialog_index < 0 || entry.dialog_index >= (int)filament_index_remap.size())
            continue;
        if (entry.kind == TextureFilamentKind::ExistingMixed)
            filament_index_remap[entry.dialog_index] = (int)(entry.project_config_index + added_physical);
    }

    const std::vector<std::string> physical_colors_for_mixing = collect_physical_color_strs();
    std::vector<MixedFilamentResult> new_mixed_results;
    std::vector<int> new_mixed_dialog_indices;
    new_mixed_results.reserve(result.new_mixed_filaments.size());
    new_mixed_dialog_indices.reserve(result.new_mixed_filaments.size());
    for (const auto& mixed : result.new_mixed_filaments) {
        MixedFilamentResult mixed_result;
        mixed_result.ratios = mixed.ratios;
        mixed_result.components.reserve(mixed.component_dialog_indices.size());
        bool valid_components = true;
        for (int component_dialog_idx : mixed.component_dialog_indices) {
            if (component_dialog_idx < 0 || component_dialog_idx >= (int)filament_index_remap.size() ||
                filament_index_remap[component_dialog_idx] < 0) {
                valid_components = false;
                break;
            }
            mixed_result.components.push_back((unsigned int)(filament_index_remap[component_dialog_idx] + 1));
        }
        if (!valid_components || mixed_result.components.size() < 2 ||
            mixed_result.components.size() != mixed_result.ratios.size()) {
            BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: invalid pending mixed filament dialog="
                                       << mixed.dialog_index;
            continue;
        }
        new_mixed_results.push_back(std::move(mixed_result));
        new_mixed_dialog_indices.push_back(mixed.dialog_index);
    }
    if (!new_mixed_results.empty()) {
        const std::vector<int> created_indices = create_mixed_filaments_from_results(
            sidebar, new_mixed_results, physical_colors_for_mixing);
        for (size_t i = 0; i < created_indices.size() && i < new_mixed_dialog_indices.size(); ++i) {
            if (created_indices[i] < 0)
                continue;
            const int dialog_index = new_mixed_dialog_indices[i];
            if (dialog_index >= 0 && dialog_index < (int)filament_index_remap.size())
                filament_index_remap[dialog_index] = created_indices[i];
            BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: created pending mixed filament dialog="
                                    << dialog_index << " final=" << created_indices[i];
        }
    }

    std::vector<Slic3r::FilamentMatch> remapped_matches = final_matches;
    for (auto& m : remapped_matches) {
        if (m.filament_index < 0)
            continue;
        if (m.filament_index < (int)filament_index_remap.size() && filament_index_remap[m.filament_index] >= 0) {
            m.filament_index = filament_index_remap[m.filament_index];
        } else {
            BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: invalid filament index "
                                       << m.filament_index << " in texture mapping";
            m.filament_index = -1;
        }
    }

    int min_used_filament_1based = -1;
    {
        std::map<std::array<std::size_t, 3>, int> color_to_filament;
        for (const auto& m : remapped_matches) {
            if (m.cluster_index >= 0 && m.cluster_index < (int)painted.cluster_colors.size() && m.filament_index >= 0)
                color_to_filament[painted.cluster_colors[m.cluster_index]] = m.filament_index + 1;
        }
        for (const auto& face_color : painted.face_colors) {
            auto it = color_to_filament.find(face_color);
            if (it == color_to_filament.end())
                continue;
            if (min_used_filament_1based < 0 || it->second < min_used_filament_1based)
                min_used_filament_1based = it->second;
        }
    }
    if (min_used_filament_1based < 0)
        BOOST_LOG_TRIVIAL(warning) << "handle_textured_mesh_import: cannot determine base filament from painted faces";

    if (!update_apply_progress(25, _L("Applying texture colors...")))
        return;

    // A standard 3MF carries exact per-triangle colors, so its volumes are painted in place
    // rather than replaced by the preview mesh. The filament creation and index remapping
    // above still apply; only the way the paint reaches the model differs.
    if (standard_3mf_color_groups != nullptr && standard_3mf_volume_colors != nullptr) {
        paint_standard_3mf_volumes(loaded_model, *standard_3mf_color_groups, *standard_3mf_volume_colors,
                                   painted, remapped_matches);
        for (size_t idx : obj_idxs) {
            if (idx >= loaded_model.objects.size() || loaded_model.objects[idx] == nullptr)
                continue;
            loaded_model.objects[idx]->invalidate_bounding_box();
            loaded_model.objects[idx]->ensure_on_bed();
            if (update_scene) {
                if (auto* obj_list = wxGetApp().obj_list())
                    obj_list->update_info_items(idx);
            }
        }
        if (update_scene) {
            if (auto* obj_list = wxGetApp().obj_list())
                obj_list->update_objects_list_filament_column(wxGetApp().filaments_cnt());
        }
        loaded_model.texture_mesh.reset();
        if (update_scene) {
            if (!update_apply_progress(90, _L("Updating 3D view...")))
                return;
            update();
        }
        update_apply_progress(100, _L("Texture colors applied."));
        return;
    }

    for (size_t obj_order = 0; obj_order < obj_idxs.size(); ++obj_order) {
        size_t idx = obj_idxs[obj_order];
        if (idx >= loaded_model.objects.size()) continue;
        ModelObject* obj = loaded_model.objects[idx];
        if (!obj) continue;

        // painted is derived from the whole textured mesh and is meaningful
        // only against a single MODEL_PART volume. Applying it to every
        // volume of a multi-part / modifier object would overwrite each
        // volume with the same painted geometry. Restrict to the first
        // model_part and warn when the object holds more than one.
        ModelVolume* target = nullptr;
        int part_count = 0;
        for (ModelVolume* vol : obj->volumes) {
            if (vol && vol->is_model_part()) {
                ++part_count;
                if (!target) target = vol;
            }
        }
        if (!target) continue;
        if (part_count > 1) {
            BOOST_LOG_TRIVIAL(warning)
                << "handle_textured_mesh_import: object has " << part_count
                << " model parts; painting only applied to the first part.";
        }
        if (Slic3r::apply_painted_mesh_to_volume(painted, remapped_matches, *target)
            && min_used_filament_1based > 0) {
            target->config.set("extruder", min_used_filament_1based);
            obj->config.set("extruder", min_used_filament_1based);
            if (update_scene) {
                if (auto* obj_list = wxGetApp().obj_list()) {
                    obj_list->update_objects_list_filament_column(std::max<size_t>(
                        wxGetApp().filaments_cnt(), (size_t)min_used_filament_1based));
                    obj_list->update_info_items(idx);
                }
            }
            BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: set base filament to "
                                    << min_used_filament_1based << " for object index " << idx
                                    << ", object extruder=" << obj->config.extruder()
                                    << ", volume extruder=" << target->config.extruder();
        }
        // bbox invalidation is performed inside apply_painted_mesh_to_volume.
        obj->ensure_on_bed();
        const int object_percent = 25 + (int)(60 * (obj_order + 1) / std::max<size_t>(obj_idxs.size(), 1));
        if (!update_apply_progress(object_percent, _L("Applying texture colors...")))
            return;
    }

    BOOST_LOG_TRIVIAL(info) << "handle_textured_mesh_import: painting applied to model volumes";
    loaded_model.texture_mesh.reset();
    if (update_scene) {
        if (!update_apply_progress(90, _L("Updating 3D view...")))
            return;
        update();
    }
    update_apply_progress(100, _L("Texture colors applied."));
}

void Plater::priv::handle_textured_mesh_import(Slic3r::Model& loaded_model, const std::vector<size_t>& obj_idxs,
                                               std::function<bool()> cancel_callback)
{
    TextureImportResult result;
    if (!run_textured_mesh_import_dialog(loaded_model, result, std::move(cancel_callback)))
        return;
    if (!result.painted.face_colors.empty())
        apply_textured_mesh_import_result(loaded_model, obj_idxs, result);
}

fs::path Plater::priv::get_export_file_path(GUI::FileType file_type)
{
    // Update printbility state of each of the ModelInstances.
    this->update_print_volume_state();

    const Selection& selection = get_selection();
    int obj_idx = selection.get_object_idx();

    fs::path output_file;
    if (file_type == FT_3MF)
        // for 3mf take the path from the project filename, if any
        output_file = into_path(get_project_filename(".3mf"));
    else if (file_type == FT_STL) {
        if (obj_idx > 0 && obj_idx < this->model.objects.size() && selection.is_single_full_object()) {
            output_file = this->model.objects[obj_idx]->get_export_filename();
        }
        else {
            output_file = into_path(get_project_name());
        }
    }
    //bbs  name the project using the part name
    if (output_file.empty()) {
        if (get_project_name() != _L("Untitled")) {
            output_file = into_path(get_project_name() + ".3mf");
        }
    }

    if (output_file.empty())
    {
        // first try to get the file name from the current selection
        if ((0 <= obj_idx) && (obj_idx < (int)this->model.objects.size()))
            output_file = this->model.objects[obj_idx]->get_export_filename();

        if (output_file.empty())
            // Find the file name of the first printable object.
            output_file = this->model.propose_export_file_name_and_path();

        if (output_file.empty() && !model.objects.empty())
            // Find the file name of the first object.
            output_file = this->model.objects[0]->get_export_filename();

        if (output_file.empty())
            // Use _L("Untitled") name
            output_file = into_path(_L("Untitled"));
    }
    return output_file;
}
bool delete_file_name_redundant_suffix(fs::path &path, const std::wstring &suffix) {
    auto temp_str = path.filename().wstring();
    boost::ireplace_last(temp_str, suffix, "");
    if (boost::icontains(temp_str, suffix)) {
        boost::ireplace_all(temp_str, suffix, "");
        std::wstring temp = L"/";
        path = (path.parent_path().wstring() + temp + temp_str + suffix);
        return true;
    }
    return false;
}

wxString Plater::priv::get_export_file(GUI::FileType file_type)
{
    wxString wildcard;
    switch (file_type) {
        case FT_STL:
        case FT_AMF:
        case FT_3MF:
        case FT_GCODE:
        case FT_OBJ:
            wildcard = file_wildcards(file_type);
        break;
        default:
            wildcard = file_wildcards(FT_MODEL);
        break;
    }

    fs::path output_file = get_export_file_path(file_type);

    wxString dlg_title;
    switch (file_type) {
        case FT_STL:
        {
            output_file.replace_extension("stl");
            dlg_title = _L("Export STL file:");
            break;
        }
        case FT_AMF:
        {
            // XXX: Problem on OS X with double extension?
            output_file.replace_extension("zip.amf");
            dlg_title = _L("Export AMF file:");
            break;
        }
        case FT_3MF:
        {
            output_file.replace_extension("3mf");
            dlg_title = _L("Save file as:");
            break;
        }
        case FT_OBJ:
        {
            output_file.replace_extension("obj");
            dlg_title = _L("Export OBJ file:");
            break;
        }
        default: break;
    }

    std::string out_dir = (boost::filesystem::path(output_file).parent_path()).string();

    wxFileDialog dlg(q, dlg_title,
        is_shapes_dir(out_dir) ? from_u8(wxGetApp().app_config->get_last_dir()) : from_path(output_file.parent_path()), from_path(output_file.filename()),
        wildcard, wxFD_SAVE | wxFD_OVERWRITE_PROMPT | wxPD_APP_MODAL);

    int result = dlg.ShowModal();
    if (result == wxID_CANCEL)
        return "<cancel>";
    if (result != wxID_OK)
        return wxEmptyString;

    wxString out_path = dlg.GetPath();
    fs::path path(into_path(out_path));
#ifdef __WXMSW__
    if (boost::iequals(path.extension().string(), output_file.extension().string()) == false) {
        out_path += output_file.extension().wstring();
        boost::system::error_code ec;
        if (boost::filesystem::exists(into_u8(out_path), ec)) {
            auto result = MessageBox(q->GetHandle(),
                wxString::Format(_L("The file %s already exists\nDo you want to replace it?"), out_path),
                _L("Comfirm Save As"),
                MB_YESNO | MB_ICONWARNING);
            if (result != IDYES)
                return wxEmptyString;
        }
    }
#endif
    if (delete_file_name_redundant_suffix(path, output_file.extension().wstring())) {
        out_path = path.wstring();
    }
    wxGetApp().app_config->update_last_output_dir(path.parent_path().string());

    return out_path;
}

