void Plater::priv::on_action_send_to_multi_app(SimpleEvent &)
{
#ifdef WIN32
    HKEY hKey;

    LONG result = RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Bambulab\\Bambu Farm Manager Client"), 0, KEY_READ, &hKey);

    if (result == ERROR_SUCCESS) {
        RegCloseKey(hKey);

        auto gcodeResult = q->send_gcode(partplate_list.get_curr_plate_index(), [this](int export_stage, int current, int total, bool &cancel) {});

        if (gcodeResult != 0) {
            BOOST_LOG_TRIVIAL(debug) << "send_gcode failed\n";
            return;
        }

        PrintPrepareData data;
        q->get_print_job_data(&data);

        if (data._3mf_path.empty()) {
            BOOST_LOG_TRIVIAL(debug) << "3mf path is empty\n";
            return;
        }

        wxString filename = q->get_export_gcode_filename("", true, partplate_list.get_curr_plate_index() == PLATE_ALL_IDX);
        wxString filepath = from_path(data._3mf_path);
        filepath.Replace("\\", "/");

        const std::string query = "?version=v1.6.0&path=" + into_u8(filepath) + "&name=" + into_u8(filename);
        const wxString    url   = from_u8("bambu-farm-client://upload-file" + Http::url_encode(query));
        if (!wxLaunchDefaultBrowser(url)) {
            GUI::MessageDialog msgdialog(nullptr, _L("Failed to start Bambu Farm Manager Client."), "", wxAPPLY | wxOK);
            msgdialog.ShowModal();
        }

    } else {
        GUI::MessageDialog msgdialog(nullptr, _L("No Bambu Farm Manager Client found."), "", wxAPPLY | wxOK);
        msgdialog.ShowModal();
    }
#endif //WIN32

#ifdef __APPLE__
    //todo
#endif //__APPLE__

}

