void Plater::priv::set_current_canvas_as_dirty()
{
    if (current_panel == view3D)
        view3D->set_as_dirty();
    else if (current_panel == preview)
        preview->set_as_dirty();
    else if (current_panel == assemble_view)
        assemble_view->set_as_dirty();
}

GLCanvas3D* Plater::priv::get_current_canvas3D(bool exclude_preview)
{
    if (current_panel == view3D)
        return view3D->get_canvas3d();
    else if (!exclude_preview && (current_panel == preview))
        return preview->get_canvas3d();
    else if (current_panel == assemble_view)
        return assemble_view->get_canvas3d();
    else //BBS default set to view3D
        return view3D->get_canvas3d();

    //return (current_panel == view3D) ? view3D->get_canvas3d() : ((current_panel == preview) ? preview->get_canvas3d() : nullptr);
}

bool Plater::priv::get_preview_min_max_value_of_option(int index, float &_min, float &_max) {
    // Access preview canvas directly - GCode data persists after slicing
    if (preview && preview->get_canvas3d()) {
        auto& gcode_viewer = preview->get_canvas3d()->get_gcode_viewer();
        return gcode_viewer.get_min_max_value_of_option(index, _min, _max);
    }
    return false;
}

int Plater::priv::get_gcode_layers_count()
{
    // Access preview canvas directly - GCode data persists after slicing
    if (preview && preview->get_canvas3d()) {
        return preview->get_canvas3d()->get_gcode_layers_count();
    }
    return 0;
}

void Plater::priv::unbind_canvas_event_handlers()
{
    if (view3D != nullptr)
        view3D->get_canvas3d()->unbind_event_handlers();

    if (preview != nullptr)
        preview->get_canvas3d()->unbind_event_handlers();

    if (assemble_view != nullptr)
        assemble_view->get_canvas3d()->unbind_event_handlers();
}

void Plater::priv::reset_canvas_volumes()
{
    if (view3D != nullptr)
        view3D->get_canvas3d()->reset_volumes();

    if (preview != nullptr)
        preview->get_canvas3d()->reset_volumes();
}

bool Plater::priv::check_ams_status_impl(bool is_slice_all)
{
    Slic3r::DeviceManager *dev = Slic3r::GUI::wxGetApp().getDeviceManager();
    if (!dev)
        return true;

    MachineObject* obj = dev->get_selected_machine();
    if (!obj || !obj->is_multi_extruders())
        return true;
    if (q->is_gcode_3mf() || q->only_gcode_mode() || q->get_partplate_list().get_curr_plate()->get_objects().empty()) {
        return true;
    }
    PresetBundle *preset_bundle = wxGetApp().preset_bundle;
    if (preset_bundle && preset_bundle->printers.get_edited_preset().get_printer_type(preset_bundle) == obj->get_show_printer_type()) {
        bool is_same_as_printer = true;
        auto nozzle_volumes_values = preset_bundle->project_config.option<ConfigOptionEnumsGeneric>("nozzle_volume_type")->values;

        assert(obj->GetExtderSystem()->GetTotalExtderCount() == 2 && nozzle_volumes_values.size() == 2);
        if (obj->GetExtderSystem()->GetTotalExtderCount() == 2 && nozzle_volumes_values.size() == 2) {
            is_same_as_printer = is_extruder_stat_synced();
        }

        std::vector<std::map<int, int>> ams_count_info;
        ams_count_info.resize(2);

        std::map<std::pair<int, int>, int> ams_cnt_map = collect_ams_counts(obj);

        int left_4  = ams_cnt_map[{0, 4}];
        int left_1  = ams_cnt_map[{0, 1}];
        int right_4 = ams_cnt_map[{1, 4}];
        int right_1 = ams_cnt_map[{1, 1}];
        const auto [l4, l1] = preset_bundle->get_ams_count(0);
        const auto [r4, r1] = preset_bundle->get_ams_count(1);
        const auto ams_ids = collect_ams_ids(obj);
        preset_bundle->initialize_ams_selection(0, obj->get_dev_id(), ams_ids.at({0, 4}), ams_ids.at({0, 1}));
        preset_bundle->initialize_ams_selection(1, obj->get_dev_id(), ams_ids.at({1, 4}), ams_ids.at({1, 1}));
        const auto *left_selection  = preset_bundle->get_ams_selection(0);
        const auto *right_selection = preset_bundle->get_ams_selection(1);
        is_same_as_printer &= left_selection && right_selection &&
                              left_selection->ams4 == ams_ids.at({0, 4}) && left_selection->ams1 == ams_ids.at({0, 1}) &&
                              right_selection->ams4 == ams_ids.at({1, 4}) && right_selection->ams1 == ams_ids.at({1, 1}) &&
                              left_4 == l4 && left_1 == l1 && right_4 == r4 && right_1 == r1;

        if (!is_same_as_printer) {
            struct SyncInfoDialog : MessageDialog
            {
                SyncInfoDialog(wxWindow *parent)
                    : MessageDialog(parent,
                                    _L("The nozzle type and AMS quantity information has not been synced from the connected printer.\n"
                                       "After syncing, software can optimize printing time and filament usage when slicing.\n"
                                       "Would you like to sync now ?"),
                                    _L("Warning"), 0)
                {
                    add_button(wxID_YES, true, _L("Sync now"));
                    add_button(wxID_NO, true, _L("Later"));
                }
            } dlg(q);
            dlg.Fit();
            if (dlg.ShowModal() == wxID_YES) {
                if (GUI::wxGetApp().sidebar().sync_extruder_list() && wxGetApp().check_slice_version_policy()) {
                    // The sync changed the nozzles, so the grouping the caller was about to check is stale: check it here,
                    // as the slice button does, before the slice request below skips straight to slicing.
                    PartPlate *plate = partplate_list.get_curr_plate();
                    if (try_pop_up_before_slice(is_slice_all, q, plate, false)) {
                        if (is_slice_all)
                            wxPostEvent(q, SimpleEvent(EVT_GLTOOLBAR_SLICE_ALL));
                        else
                            wxPostEvent(q, SimpleEvent(EVT_GLTOOLBAR_SLICE_PLATE));
                        // The slice request switches to the preview itself. SetSelection would enter it a second time
                        // through the tab event, which runs the sync popup, the grouping dialog and the slice again.
                        wxGetApp().mainframe->m_tabpanel->ChangeSelection(MainFrame::TabPosition::tpPreview);
                    }
                }
                return false;
            }
        }
    }

    return true;
}

bool Plater::priv::get_machine_sync_status()
{
    Slic3r::DeviceManager *dev = Slic3r::GUI::wxGetApp().getDeviceManager();
    if (!dev)
        return false;

    MachineObject* obj = dev->get_selected_machine();
    if (!obj)
        return false;

    PresetBundle *preset_bundle = wxGetApp().preset_bundle;
    return preset_bundle && preset_bundle->printers.get_edited_preset().get_printer_type(preset_bundle) == obj->get_show_printer_type();
}

Camera& Plater::priv::get_current_camera()
{
    if (current_panel == assemble_view) {
        if (assemble_view) {
            const auto& p_camera = assemble_view->get_override_camera();
            if (p_camera) {
                p_camera->set_type(camera.get_type());
                return *p_camera;
            }
        }
    }
    return camera;
}

bool Plater::priv::init_collapse_toolbar()
{
    if (wxGetApp().is_gcode_viewer())
        return true;

    if (collapse_toolbar.get_items_count() > 0)
        // already initialized
        return true;

    BackgroundTexture::Metadata background_data;
    background_data.filename = m_is_dark ? "toolbar_background_dark.png" : "toolbar_background.png";
    background_data.left = 4;
    background_data.top = 4;
    background_data.right = 4;
    background_data.bottom = 4;

    if (!collapse_toolbar.init(background_data))
        return false;

    collapse_toolbar.set_layout_type(ToolbarLayout::EType::Vertical);
    collapse_toolbar.set_horizontal_orientation(ToolbarLayout::HO_Right);
    collapse_toolbar.set_vertical_orientation(ToolbarLayout::VO_Top);
    collapse_toolbar.set_border(0.0f);
    collapse_toolbar.set_separator_size(5);
    collapse_toolbar.set_gap_size(2);
    collapse_toolbar.del_all_item();
    collapse_toolbar.set_position_mode(ToolbarLayout::EPositionMode::TopLeft);

    GLToolbarItem::Data item;

    item.name = "collapse_sidebar";
    item.icon_filename_callback = [](bool is_dark_mode)->std::string {
        return "collapse.svg";
    };
    item.sprite_id = 0;
    item.left.action_callback = []() {
        wxGetApp().plater()->collapse_sidebar(!wxGetApp().plater()->is_sidebar_collapsed());
    };

    if (!collapse_toolbar.add_item(item))
        return false;

    // Now "collapse" sidebar to current state. This is done so the tooltip
    // is updated before the toolbar is first used.
    wxGetApp().plater()->collapse_sidebar(wxGetApp().plater()->is_sidebar_collapsed());
    collapse_toolbar.set_icons_size(q->get_collapse_toolbar_size());
    return true;
}

