void Plater::undo() { p->undo(); }
void Plater::redo() { p->redo(); }
void Plater::undo_redo_to(size_t time_to_load) { p->undo_redo_to(time_to_load); }
void Plater::undo_to(int selection)
{
    if (selection == 0) {
        p->undo();
        return;
    }

    const int idx = p->get_active_snapshot_index() - selection - 1;
    p->undo_redo_to(p->undo_redo_stack().snapshots()[idx].timestamp);
}
void Plater::redo_to(int selection)
{
    if (selection == 0) {
        p->redo();
        return;
    }

    const int idx = p->get_active_snapshot_index() + selection + 1;
    p->undo_redo_to(p->undo_redo_stack().snapshots()[idx].timestamp);
}
bool Plater::undo_redo_string_getter(const bool is_undo, int idx, const char** out_text)
{
    const std::vector<UndoRedo::Snapshot>& ss_stack = p->undo_redo_stack().snapshots();
    const int idx_in_ss_stack = p->get_active_snapshot_index() + (is_undo ? -(++idx) : idx);

    if (0 < idx_in_ss_stack && (size_t)idx_in_ss_stack < ss_stack.size() - 1) {
        *out_text = ss_stack[idx_in_ss_stack].name.c_str();
        return true;
    }

    return false;
}

int Plater::update_print_required_data(Slic3r::DynamicPrintConfig config, Slic3r::Model model, Slic3r::PlateDataPtrs plate_data_list, std::string file_name, std::string file_path)
{
    return p->update_print_required_data(config, model, plate_data_list, file_name, file_path);
}


void Plater::undo_redo_topmost_string_getter(const bool is_undo, std::string& out_text)
{
    const std::vector<UndoRedo::Snapshot>& ss_stack = p->undo_redo_stack().snapshots();
    const int idx_in_ss_stack = p->get_active_snapshot_index() + (is_undo ? -1 : 0);

    if (0 < idx_in_ss_stack && (size_t)idx_in_ss_stack < ss_stack.size() - 1) {
        out_text = ss_stack[idx_in_ss_stack].name;
        return;
    }

    out_text = "";
}

bool Plater::search_string_getter(int idx, const char** label, const char** tooltip)
{
    const Search::OptionsSearcher& search_list = p->sidebar->get_searcher();

    if (0 <= idx && (size_t)idx < search_list.size()) {
        search_list[idx].get_marked_label_and_tooltip(label, tooltip);
        return true;
    }

    return false;
}

bool Plater::on_filament_change(size_t filament_idx)
{
    auto& filament_presets = wxGetApp().preset_bundle->filament_presets;
    if (filament_idx >= filament_presets.size())
        return false;
    Slic3r::Preset* filament = wxGetApp().preset_bundle->filaments.find_preset(filament_presets[filament_idx]);
    if (filament == nullptr)
        return false;
    std::string filament_type = filament->config.option<ConfigOptionStrings>("filament_type")->values[0];
    if (filament_type == "PVA") {
        auto nozzle_diameters = p->config->option<ConfigOptionFloatsNullable>("nozzle_diameter")->values;
        if (std::find(nozzle_diameters.begin(), nozzle_diameters.end(), 0.2) != nozzle_diameters.end()) {
            // Gate the warning on the current printer model's own preset data instead of a hardcoded
            // model check: a model whose preset library never shipped a 0.2mm-compatible PVA preset
            // never offers "0.2" here, so this slot could not actually reach that combination through
            // the normal selector in the first place -- the warning would be unreachable noise there.
            const auto options = wxGetApp().preset_bundle->get_filament_nozzle_diameter_options(filament_idx);
            const bool model_offers_0_2mm_pva_preset =
                std::find(options.begin(), options.end(), std::string("0.2")) != options.end();
            if (model_offers_0_2mm_pva_preset) {
                wxString msg_text = _(L("It is not recommended to use PVA filaments with 0.2mm nozzles."));
                msg_text += "\n" + _(L("Are you sure to use them? \n"));
                MessageDialog dialog(wxGetApp().plater(), msg_text, "", wxICON_WARNING | wxYES | wxNO);
                if (dialog.ShowModal() == wxID_NO) {
                    return false;
                }
            }
        }
    }
    return true;
}

// BBS.
void Plater::on_filament_count_change(size_t num_filaments)
{
    // only update elements in plater
    update_filament_colors_in_full_config();
    sidebar().on_filament_count_change(num_filaments);
    sidebar().obj_list()->update_objects_list_filament_column(num_filaments);

    Slic3r::GUI::PartPlateList &plate_list = get_partplate_list();
    plate_list.set_filament_count(num_filaments);
    for (int i = 0; i < plate_list.get_plate_count(); ++i) {
        PartPlate* part_plate = plate_list.get_plate(i);
        part_plate->update_first_layer_print_sequence(num_filaments);
    }

    for (ModelObject* mo : wxGetApp().model().objects) {
        for (ModelVolume* mv : mo->volumes) {
            mv->update_extruder_count(num_filaments);
        }
    }
}

void Plater::on_filaments_delete(size_t num_filaments, size_t filament_id, int replace_filament_id, const std::vector<unsigned char>& is_mixed_before_delete)
{
    // only update elements in plater
    update_filament_colors_in_full_config();

    // update fisrt print sequence and other layer sequence
    //move to partplate->on_filament_deleted
    /*Slic3r::GUI::PartPlateList &plate_list = get_partplate_list();
    for (int i = 0; i < plate_list.get_plate_count(); ++i) {
        PartPlate *part_plate = plate_list.get_plate(i);
        part_plate->update_first_layer_print_sequence_when_delete_filament(filament_id);
    }*/

    // update mmu paint data
    const auto &is_mixed = is_mixed_before_delete.empty()
        ? wxGetApp().preset_bundle->project_config.option<ConfigOptionBools>("filament_is_mixed")->values
        : is_mixed_before_delete;
    for (ModelObject *mo : wxGetApp().model().objects) {
        for (ModelVolume *mv : mo->volumes) {
            mv->update_extruder_count_when_delete_filament(num_filaments, filament_id + 1, replace_filament_id + 1, is_mixed);
        }
    }

    // update object/volume/support(object and volume) filament id
    // Must run before UI update which triggers update_mixed_filament_list() →
    // update_objects_list_filament_column() that clips extruders above total count.
    sidebar().obj_list()->update_objects_list_filament_column_when_delete_filament(filament_id, num_filaments, replace_filament_id);

    // update global feature filaments: when the deleted filament was selected it
    // becomes "Default" (0) on a plain delete, or follows the target on a "Merge with"; otherwise the
    // stored index is shifted down. Apply to both the edited print preset (drives slicing and the Print
    // tab) and the Plater's cached subset so they stay consistent.
    static const char *keys[] = {"support_filament", "support_interface_filament",
                                 "wall_filament", "sparse_infill_filament", "solid_infill_filament"};
    auto               remap_support_filament = [&](DynamicPrintConfig &cfg) {
        for (auto key : keys) {
            if (!cfg.has(key)) continue;
            const int v = cfg.opt_int(key);
            if (v == (int) filament_id + 1)
                cfg.set_key_value(key, new ConfigOptionInt(replace_filament_id + 1)); // -1 -> 0 (Default), else remapped target
            else if (v > (int) filament_id + 1)
                cfg.set_key_value(key, new ConfigOptionInt(v - 1));
        }
    };
    remap_support_filament(*p->config);
    remap_support_filament(wxGetApp().preset_bundle->prints.get_edited_preset().config);
    // The remap bypasses Tab::on_value_change(), so refresh the modified/reset marks as well.
    if (Tab *print_tab = wxGetApp().get_tab(Preset::TYPE_PRINT)) {
        print_tab->update_dirty();
        print_tab->reload_config();
    }

    // update UI — runs after remap so update_mixed_filament_list() won't clip remapped extruder IDs
    sidebar().on_filaments_delete(filament_id);

    // update customize gcode
    for (auto item = p->model.plates_custom_gcodes.begin(); item != p->model.plates_custom_gcodes.end(); ++item) {
        auto iter = std::remove_if(item->second.gcodes.begin(), item->second.gcodes.end(), [filament_id](const Item& gcode_item) {
            return (gcode_item.type == CustomGCode::Type::ToolChange && gcode_item.extruder == filament_id + 1);
        });
        if (replace_filament_id == -1)
            item->second.gcodes.erase(iter, item->second.gcodes.end());
        else if(iter != item->second.gcodes.end()) {
            iter->extruder = replace_filament_id + 1;
        }

        for (auto& item : item->second.gcodes) {
            if (item.type == CustomGCode::Type::ToolChange && item.extruder > filament_id)
                item.extruder--;
        }
    }
}

void Plater::replace_filament_on_model(size_t from_id, size_t to_id)
{
    if (from_id == to_id || to_id + 1 > size_t(EnforcerBlockerType::ExtruderMax))
        return;

    take_snapshot("Replace filament on models");

    const EnforcerBlockerType from_state = EnforcerBlockerType(from_id + 1);
    const EnforcerBlockerType to_state   = EnforcerBlockerType(to_id + 1);
    for (ModelObject *mo : p->model.objects)
        for (ModelVolume *mv : mo->volumes)
            mv->mmu_segmentation_facets.replace_state(*mv, from_state, to_state);

    sidebar().obj_list()->update_filament_values_for_items_when_replace_filament(from_id, to_id);

    for (auto &plate_gcodes : p->model.plates_custom_gcodes)
        for (Item &gcode_item : plate_gcodes.second.gcodes)
            if (gcode_item.type == CustomGCode::Type::ToolChange && gcode_item.extruder == int(from_id) + 1)
                gcode_item.extruder = int(to_id) + 1;

    sidebar().obj_list()->update_filament_colors();
    update();
}

// Physical filaments always precede mixed ones, so a change in the physical count moves every mixed
// filament id (1-based, above old_physical_count) by the difference. Physical ids in
// (new_physical_count, old_physical_count] no longer exist and fall back to the default filament.
// Must run before on_filament_count_change(), which clears ids above the new total.
void Plater::remap_mixed_filament_ids(size_t old_physical_count, size_t new_physical_count)
{
    if (old_physical_count == new_physical_count)
        return;
    const int old_n        = int(old_physical_count);
    const int new_n        = int(new_physical_count);
    const int delta        = new_n - old_n;
    const int total_after  = int(wxGetApp().preset_bundle->filament_presets.size());
    const int total_before = total_after - delta;
    if (total_before <= old_n || total_after <= new_n)
        return;

    BOOST_LOG_TRIVIAL(info) << "physical " << old_n << " -> " << new_n << ", total " << total_before << " -> " << total_after;

    // old_to_new[i] is the new 1-based id of old filament i + 1; 0 means it no longer exists.
    // Ids pushed beyond ExtruderMax cannot be painted or selected, so they are dropped as well.
    const int max_id = int(EnforcerBlockerType::ExtruderMax);
    std::vector<int> old_to_new(total_before);
    for (int id = 1; id <= total_before; ++id) {
        const int new_id   = id > old_n ? id + delta : (id > new_n ? 0 : id);
        old_to_new[id - 1] = new_id > max_id ? 0 : new_id;
    }
    auto remap = [&old_to_new](int id) { return (id >= 1 && id <= int(old_to_new.size())) ? old_to_new[id - 1] : id; };

    auto remap_option = [&remap](ModelConfig &cfg, const std::string &key, bool erase_removed) {
        if (!cfg.has(key))
            return;
        const int v  = cfg.opt_int(key);
        const int nv = remap(v);
        if (nv == v)
            return;
        if (nv == 0 && erase_removed)
            cfg.erase(key);
        else
            cfg.set_key_value(key, new ConfigOptionInt(nv));
    };
    // Height range modifiers always carry "extruder", so a removed id becomes 0 (Default) there instead of being erased.
    auto remap_model_config = [&remap_option](ModelConfig &cfg, bool erase_removed_extruder) {
        remap_option(cfg, "extruder", erase_removed_extruder);
        for (const std::string &key : filament_index_object_keys())
            remap_option(cfg, key, true);
    };

    for (ModelObject *mo : p->model.objects) {
        remap_model_config(mo->config, true);
        for (ModelVolume *mv : mo->volumes) {
            remap_model_config(mv->config, true);
            if (mv->mmu_segmentation_facets.empty())
                continue;
            // Clear dropped ids first so the shift below cannot land surviving states on them.
            for (int id = 1; id <= total_before; ++id)
                if (old_to_new[id - 1] == 0)
                    mv->mmu_segmentation_facets.replace_state(*mv, EnforcerBlockerType(id), EnforcerBlockerType::NONE);
            mv->mmu_segmentation_facets.shift_states_above(*mv, EnforcerBlockerType(old_n + 1), delta);
        }
        for (auto &range : mo->layer_config_ranges)
            remap_model_config(range.second, false);
    }
    // Object / part rows are refreshed by on_filament_count_change(), height range rows are not.
    sidebar().obj_list()->update_layer_range_filament_values();

    bool support_changed        = false;
    auto remap_support_filament = [&remap, &support_changed](DynamicPrintConfig &cfg) {
        for (const char *key : {"support_filament", "support_interface_filament"}) {
            if (!cfg.has(key))
                continue;
            const int v  = cfg.opt_int(key);
            const int nv = remap(v);
            if (nv != v) {
                cfg.set_key_value(key, new ConfigOptionInt(nv));
                support_changed = true;
            }
        }
    };
    remap_support_filament(*p->config);
    remap_support_filament(wxGetApp().preset_bundle->prints.get_edited_preset().config);
    if (support_changed)
        if (Tab *print_tab = wxGetApp().get_tab(Preset::TYPE_PRINT)) {
            print_tab->update_dirty();
            print_tab->reload_config();
        }

    for (auto &plate_gcodes : p->model.plates_custom_gcodes) {
        auto &gcodes = plate_gcodes.second.gcodes;
        gcodes.erase(std::remove_if(gcodes.begin(), gcodes.end(),
                                    [&remap](const CustomGCode::Item &item) {
                                        return item.type == CustomGCode::Type::ToolChange && item.extruder > 0 && remap(item.extruder) == 0;
                                    }),
                     gcodes.end());
        for (CustomGCode::Item &item : gcodes)
            if (item.type == CustomGCode::Type::ToolChange)
                item.extruder = remap(item.extruder);
    }
}

std::vector<std::array<float, 4>> Plater::get_extruders_colors()
{
    unsigned char                     rgba_color[4] = {};
    std::vector<std::string>          colors        = get_extruder_colors_from_plater_config();
    std::vector<std::array<float, 4>> colors_out(colors.size());
    for (const std::string &color : colors) {
        Slic3r::GUI::BitmapCache::parse_color4(color, rgba_color);
        size_t color_idx      = &color - &colors.front();
        colors_out[color_idx] = {
            float(rgba_color[0]) / 255.f,
            float(rgba_color[1]) / 255.f,
            float(rgba_color[2]) / 255.f,
            float(rgba_color[3]) / 255.f,
        };
    }
    return colors_out;
}

void Plater::on_bed_type_change(BedType bed_type, bool is_gcode_file) {
    sidebar().set_is_gcode_file(is_gcode_file);
    sidebar().on_bed_type_change(bed_type);
}

bool Plater::update_filament_colors_in_full_config()
{
    const auto& project_config = wxGetApp().preset_bundle->project_config;
    const auto& full_config = wxGetApp().preset_bundle->full_config();
    const ConfigOptionStrings* color_opt = project_config.option<ConfigOptionStrings>("filament_colour");
    const ConfigOptionStrings* type_opt = full_config.option<ConfigOptionStrings>("filament_type");

    auto& cfg_colours = p->config->option<ConfigOptionStrings>("filament_colour")->values;
    cfg_colours = color_opt->values;
    p->config->option<ConfigOptionStrings>("filament_type")->values = type_opt->values;

    // full_config() truncates filament_colour to physical filament count.
    // Patch with project_config which has the full list including mixed slots.
    const auto* proj_colours = project_config.option<ConfigOptionStrings>("filament_colour");
    if (proj_colours && proj_colours->values.size() > cfg_colours.size()) {
        for (size_t i = cfg_colours.size(); i < proj_colours->values.size(); ++i)
            cfg_colours.push_back(proj_colours->values[i]);
    }

    return true;
}

void Plater::config_change_notification(const DynamicPrintConfig &config, const std::string& key)
{
    GLCanvas3D* view3d_canvas = get_view3D_canvas3D();
    if (key == std::string("print_sequence")) {
        auto seq_print = config.option<ConfigOptionEnum<PrintSequence>>("print_sequence");
        if (seq_print && view3d_canvas && view3d_canvas->is_initialized() && view3d_canvas->is_rendering_enabled()) {
            NotificationManager* notify_manager = get_notification_manager();
            if (seq_print->value == PrintSequence::ByObject) {
                show_seqprintinfo_notification(false);
            }
            else
                notify_manager->bbl_close_seqprintinfo_notification();
        }
    }
    // notification for more options
}

void Plater::on_config_change(const DynamicPrintConfig &config)
{
    bool update_scheduled = false;
    bool bed_shape_changed = false;
    //bool print_sequence_changed = false;
    t_config_option_keys diff_keys = p->config->diff(config);

    size_t old_nozzle_size = 1, new_nozzle_size = 1;
    auto * opt_old = p->config->option<ConfigOptionFloatsNullable>("nozzle_diameter");
    auto * opt_new = config.option<ConfigOptionFloatsNullable>("nozzle_diameter");
    if (opt_old && opt_new) {
        old_nozzle_size = opt_old->values.size();
        new_nozzle_size = opt_new->values.size();
    }
    auto temp_is_system_preset = cur_selected_preset_is_system_preset();
    bool preset_custom_change = false;
    if (temp_is_system_preset != m_last_is_system_preset) {
        m_last_is_system_preset = temp_is_system_preset;
        preset_custom_change = true;
    }
    for (auto opt_key : diff_keys) {
        if (opt_key == "filament_colour") {
            update_scheduled = true; // update should be scheduled (for update 3DScene) #2738

            if (update_filament_colors_in_full_config()) {
                p->sidebar->update_mixed_filament_list();
                dynamic_filament_list.update();
                continue;
            }
        }
        if (opt_key == "filament_type") {
            update_filament_colors_in_full_config();
            p->sidebar->update_mixed_filament_list();
            continue;
        }
        if (opt_key == "filament_is_support") {
            p->config->set_key_value(opt_key, config.option(opt_key)->clone());
            p->sidebar->update_mixed_filament_list();
            continue;
        }
        if (opt_key == "material_colour") {
            update_scheduled = true; // update should be scheduled (for update 3DScene)
        }

        p->config->set_key_value(opt_key, config.option(opt_key)->clone());
        if (opt_key == "printer_technology") {
            this->set_printer_technology(config.opt_enum<PrinterTechnology>(opt_key));
            // print technology is changed, so we should to update a search list
            p->sidebar->update_searcher();
            p->reset_gcode_toolpaths();
            p->view3D->get_canvas3d()->reset_sequential_print_clearance();
            //BBS: invalid all the slice results
            p->partplate_list.invalid_all_slice_result();
        }
        //BBS: add bed_exclude_area
        else if (opt_key == "printable_area" || opt_key == "bed_exclude_area"
            || opt_key == "bed_heat_soak_area"
            || opt_key == "extruder_clearance_height_to_lid"
            || opt_key == "extruder_clearance_height_to_rod") {
            bed_shape_changed = true;
            update_scheduled = true;
        }
        else if (opt_key == "bed_shape" || opt_key == "bed_custom_texture" || opt_key == "bed_custom_model") {
            bed_shape_changed = true;
            update_scheduled = true;
        }
        else if (boost::starts_with(opt_key, "enable_prime_tower") ||
            boost::starts_with(opt_key, "prime_tower") ||
            boost::starts_with(opt_key, "wipe_tower") ||
            // opt_key == "filament_minimal_purge_on_wipe_tower" // ? #ys_FIXME
            opt_key == "single_extruder_multi_material") {
            update_scheduled = true;
        }
        else if(opt_key == "extruder_colour") {
            update_scheduled = true;
            //p->sidebar->obj_list()->update_extruder_colors();
        }
        else if (opt_key == "printable_height") {
            bed_shape_changed = true;
            update_scheduled = true;
        }
        else if (opt_key == "print_sequence") {
            update_scheduled = true;
            //print_sequence_changed = true;
        }
        else if (opt_key == "printer_model") {
            p->reset_gcode_toolpaths();
            if (old_nozzle_size != new_nozzle_size) {
                update_flush_volume_matrix(old_nozzle_size, new_nozzle_size);
            }
            set_global_filament_map_mode(fmmAutoForFlush);

            // update to force bed selection(for texturing)
            bed_shape_changed = true;
            update_scheduled = true;
        }
        // BBS
        else if (opt_key == "support_interface_filament" || opt_key == "support_filament" || opt_key == "wall_filament" || opt_key == "sparse_infill_filament" ||
                 opt_key == "solid_infill_filament") {
            update_scheduled = true;
        }
    }

    if (bed_shape_changed || preset_custom_change) {
        set_bed_shape();
    }

    config_change_notification(config, std::string("print_sequence"));

    if (update_scheduled)
        update();

    if (p->main_frame->is_loaded())
        this->p->schedule_background_process();
}

bool Plater::cur_selected_preset_is_system_preset()
{
    PresetBundle &preset_bundle = *wxGetApp().preset_bundle;
    auto &        selected_preset = preset_bundle.printers.get_selected_preset();
    //bool is_bbl_preset = preset_bundle.printers.get_edited_preset().is_bbl_vendor_preset(&preset_bundle);
    return selected_preset.is_system;
}

void Plater::update_flush_volume_matrix(size_t old_nozzle_size, size_t new_nozzle_size)
{
    size_t nozzle_nums = wxGetApp().preset_bundle->get_printer_extruder_count();
    Slic3r::DynamicPrintConfig *project_config = &wxGetApp().preset_bundle->project_config;

    // Verify whether it is the first time start Studio
    size_t filament_nums = project_config->option<ConfigOptionStrings>("filament_colour")->values.size();
    size_t flush_volume_size = project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values.size();

    assert(nozzle_nums == new_nozzle_size);
    if (old_nozzle_size < new_nozzle_size) {

        std::vector<double>  first_flush_volume_mtx = get_flush_volumes_matrix(project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values, -1, old_nozzle_size);
        if (first_flush_volume_mtx.size() == filament_nums * filament_nums * new_nozzle_size) { // load file
            set_flush_volumes_matrix(project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values, first_flush_volume_mtx, -1, new_nozzle_size);
        } else {
            first_flush_volume_mtx.resize(filament_nums * filament_nums);
            std::vector<double> flush_volume_mtx;
            for (size_t i = 0; i < new_nozzle_size; ++i) {
                flush_volume_mtx.insert(flush_volume_mtx.end(), first_flush_volume_mtx.begin(), first_flush_volume_mtx.end());
            }
            set_flush_volumes_matrix(project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values, flush_volume_mtx, -1, new_nozzle_size);
        }
        std::vector<double> flush_multipliers = project_config->option<ConfigOptionFloats>("flush_multiplier")->values;
        flush_multipliers.resize(nozzle_nums, 1.f);
        project_config->option<ConfigOptionFloats>("flush_multiplier")->values = flush_multipliers;
        std::vector<double> flush_multipliers_fast                             = project_config->option<ConfigOptionFloats>("flush_multiplier_fast")->values;
        flush_multipliers_fast.resize(nozzle_nums, 1.2f);
        project_config->option<ConfigOptionFloats>("flush_multiplier_fast")->values = flush_multipliers_fast;
    }
    else if (old_nozzle_size > new_nozzle_size) {
        std::vector<double> new_flush_volume_mtx;
        for (size_t i = 0; i < new_nozzle_size; ++i) {
            std::vector<double> flush_volume_mtx = get_flush_volumes_matrix(project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values, -1, old_nozzle_size);
            flush_volume_mtx.resize(filament_nums * filament_nums);
            new_flush_volume_mtx.insert(new_flush_volume_mtx.end(), flush_volume_mtx.begin(), flush_volume_mtx.end());
        }

        std::vector<double> flush_multipliers = project_config->option<ConfigOptionFloats>("flush_multiplier")->values;
        flush_multipliers.resize(nozzle_nums, 1.f);
        set_flush_volumes_matrix(project_config->option<ConfigOptionFloats>("flush_volumes_matrix")->values, new_flush_volume_mtx, -1, new_nozzle_size);
        project_config->option<ConfigOptionFloats>("flush_multiplier")->values = flush_multipliers;
        std::vector<double> flush_multipliers_fast                             = project_config->option<ConfigOptionFloats>("flush_multiplier_fast")->values;
        flush_multipliers_fast.resize(nozzle_nums, 1.2f);
        project_config->option<ConfigOptionFloats>("flush_multiplier_fast")->values = flush_multipliers_fast;
    }
}

void Plater::set_bed_shape() const
{
    std::string texture_filename;
    auto bundle = wxGetApp().preset_bundle;
    if (bundle != nullptr) {
        const Preset* curr = &bundle->printers.get_selected_preset();
        if (curr->is_system) {
            texture_filename = PresetUtils::system_printer_bed_texture(*curr);
            bool is_configed_by_BBL = PresetUtils::system_printer_bed_model(*curr).size() > 0;
            if (is_configed_by_BBL) {
                bool is_bbl_preset = bundle->printers.get_selected_preset().is_bbl_vendor_preset(bundle);
                if (wxGetApp().app_config->has_section("user_bbl_svg_list")) {
                    auto cur_preset_name   = bundle->printers.get_edited_preset().name;
                    auto user_bbl_svg_list = wxGetApp().app_config->get_section("user_bbl_svg_list");
                    if (user_bbl_svg_list.size() > 0 && user_bbl_svg_list[cur_preset_name].size() > 0) {
                        texture_filename = user_bbl_svg_list[cur_preset_name];
                    } else {
                        if (is_bbl_preset) {
                            texture_filename = "";
                        }
                    }
                } else if (is_bbl_preset) {
                    texture_filename = "";
                }
            }
        }
        else {
            auto *bed_custom_texture = curr->config.opt<ConfigOptionString>("bed_custom_texture");
            texture_filename         = bed_custom_texture->value;
        }
    }
    set_bed_shape(p->config->option<ConfigOptionPoints>("printable_area")->values,
        //BBS: add bed exclude areas
        p->config->option<ConfigOptionPoints>("bed_exclude_area")->values,
        p->config->option<ConfigOptionPoints>("wrapping_exclude_area")->values,
        p->config->option<ConfigOptionFloat>("printable_height")->value,
        p->config->option<ConfigOptionPointsGroups>("extruder_printable_area")->values,
        p->config->option<ConfigOptionFloatsNullable>("extruder_printable_height")->values,
        p->config->option<ConfigOptionString>("bed_custom_texture")->value.empty() ? texture_filename : p->config->option<ConfigOptionString>("bed_custom_texture")->value,
        p->config->option<ConfigOptionString>("bed_custom_model")->value);
}

//BBS: add bed exclude area
void Plater::set_bed_shape(const Pointfs& shape, const Pointfs& exclude_area, const Pointfs& wrapping_exclude_area, const double printable_height, std::vector<Pointfs> extruder_areas, std::vector<double> extruder_heights, const std::string& custom_texture, const std::string& custom_model, bool force_as_custom) const
{
    p->set_bed_shape(shape, exclude_area, wrapping_exclude_area, printable_height, extruder_areas, extruder_heights, custom_texture, custom_model, force_as_custom);
}

