void Plater::update_filament_volume_map(int extruder_id, int volume_type)
{
    PresetBundle *preset_bundle = wxGetApp().preset_bundle;
    if (preset_bundle != nullptr &&
        multi_nozzle_diameter_mode_enabled(preset_bundle->project_config) &&
        is_single_ext_multi_nozzle(preset_bundle->printers.get_edited_preset().config)) {
        // In this mode filament_volume_map is the flow selected per filament in the sidebar. Every
        // filament_map entry is 1 because the machine has one logical extruder, so applying the
        // extruder's representative flow below would overwrite every independent selection whenever
        // the machine setup refreshes (notably after adding/removing an external AMS).
        const auto *selected = preset_bundle->project_config.option<ConfigOptionInts>("filament_volume_map");
        if (selected != nullptr) {
            for (PartPlate *plate : get_partplate_list().get_plate_list())
                if (plate != nullptr)
                    plate->set_filament_volume_maps(selected->values);
        }
        return;
    }

    int   selected_volume_type = volume_type == static_cast<int>(NozzleVolumeType::nvtHybrid) ? 0 : volume_type;
    auto& partplate_list       = get_partplate_list();
    for (int idx = 0; idx < partplate_list.get_plate_count(); ++idx) {
        auto plate = partplate_list.get_plate(idx);
        if (!plate) continue;
        auto filament_map        = plate->get_filament_maps();
        auto filament_volume_map = plate->get_filament_volume_maps();
        if (filament_map.empty() || filament_volume_map.empty()) continue;
        if (filament_volume_map.size() < filament_map.size()) {
            filament_volume_map.resize(filament_map.size(), 0);
        }
        for (int i = 0; i < filament_map.size(); ++i) {
            if (filament_map[i] == extruder_id + 1) {
                filament_volume_map[i] = selected_volume_type;
            }
        }
        plate->set_filament_volume_maps(filament_volume_map);
    }
}

void Plater::show_wrapping_detect_dialog_if_necessary()
{
    if ((wxGetApp().app_config->get("show_wrapping_detect_dialog") == "true")) {
        std::string printer_type = wxGetApp().preset_bundle->printers.get_edited_preset().get_printer_type(wxGetApp().preset_bundle);
        if (DevPrinterConfigUtil::support_wrapping_detection(printer_type)) {
            ImageMessageDialog dlg(this, wxID_ANY, _L("Parameter recommendation"), _L("In the process preset, under \"Others-Advanced\", check \"Enable clumping detection by probing\". This feature generates a small wipe "
                "tower and performs probing detection to identify clumping issues early in the print and stop printing, preventing print failures or printer damage.\n"));
            dlg.ShowModal();
            wxGetApp().app_config->set("show_wrapping_detect_dialog", "false");
        }
    }
}

